/* Câu hỏi các đề GDCD lớp 9 có sẵn. Danh mục (tên, khối, môn, số phút, số câu): data/banks/index.js.
   App chỉ tải file này khi mở một đề trong đó. Dạng câu hỏi: xem đầu data/banks/index.js. */
window.ONTAP_SEED_QUESTIONS = Object.assign(window.ONTAP_SEED_QUESTIONS || {}, {
  /* ---------- GDCD 9 · Kiểm tra giữa học kì I (Kết nối tri thức; Phiên N9-gk1-lsdl-gdcd) ----------
     Sách Giáo dục công dân 9 in năm 2026 (OnUp-Book lop-9/giao-duc-cong-dan-9), Bài 1–3: Sống có lí tưởng; Khoan dung; Tích cực tham gia
     các hoạt động cộng đồng (chữ chủ đề “Hoạt động cộng đồng” như kho cuối kì I, nên đề “Ôn chủ đề” rút chung câu của hai kho: câu ở đây
     không trùng ý, không lộ đáp án câu cùng chủ đề của kho cuối kì I). Câu tự soạn: tình huống, nhân vật không lấy từ sách (nhân vật của
     sách mang tên một chữ cái), không dùng lại các nhận định của phần Luyện tập. Hai đề là kho của đề ngẫu nhiên "gdcd9-gk1-ngau-nhien"
     (không có câu riêng nên không ghi vào file này; ma trận ở data/banks/index.js). Mỗi đề 25 câu chia đúng ma trận 10 Biết, 8 Hiểu, 7 Vận
     dụng: Sống có lí tưởng, Khoan dung mỗi bài 8 câu, Hoạt động cộng đồng 9 câu; ô rút k câu có 2k câu (mỗi đề k câu), nên câu cùng ô
     cũng không ghi sẵn đáp án của nhau. Cách xếp mức như kho cuối kì I: nêu khái niệm, ý nghĩa, biểu hiện, nhóm hoạt động, thành ngữ là
     Biết; nhận xét việc làm, ý kiến của một người, giải thích vì sao là Hiểu; xử lí tình huống là Vận dụng. Câu tình huống là chính. */
  "gdcd9-gk1-de1": {
    note: "Giáo dục công dân 9, sách Kết nối tri thức, giữa học kì I: Bài 1 Sống có lí tưởng; Bài 2 Khoan dung; Bài 3 Tích cực tham gia các hoạt động cộng đồng. Câu tình huống là chính. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Phạm vi của trường có thể khác, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu.",
    questions: [
      { topic: "Sống có lí tưởng", type: "mc", q: "Lí tưởng của một người được hiểu là gì?", o: ["Điều tốt đẹp nhất mà người đó chọn làm đích đến và dốc sức phấn đấu để đạt được", "Những thú vui giúp người đó giải trí, nghỉ ngơi sau giờ học tập và lao động", "Mức thu nhập cao nhất mà người đó mong có được trong suốt cuộc đời của mình", "Những việc người khác đặt ra và bắt buộc người đó phải làm theo đúng từng bước một"], x: "Lí tưởng là đích đến tốt đẹp nhất mà mỗi người chọn cho cuộc đời mình và quyết tâm phấn đấu để đạt tới. Thú vui giải trí, chuyện thu nhập hay việc do người khác áp đặt đều không phải là lí tưởng.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Câu nào sau đây là lời kêu gọi thanh niên xung phong nhận việc khó, có mặt ở những nơi đang cần mình?", o: ["Đâu cần thanh niên có, việc gì khó thanh niên làm", "Lá lành đùm lá rách, lá rách ít đùm lá rách nhiều", "Uống nước nhớ nguồn, ăn quả nhớ kẻ trồng cây", "Bầu ơi thương lấy bí cùng, tuy rằng khác giống nhưng chung một giàn"], x: "“Đâu cần thanh niên có, việc gì khó thanh niên làm” nhắc thanh niên đến những nơi gian khổ, nhận những việc nặng nhọc. Ba câu còn lại khuyên con người thương yêu, đùm bọc nhau và biết ơn người đi trước.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "tf4", q: "Mỗi ý sau về lí tưởng mà thanh niên nước ta hôm nay theo đuổi đúng hay sai?", o: ["Rèn luyện sức khoẻ, ra sức học tập để có năng lực, bản lĩnh và trở thành người công dân tốt.", "Lí tưởng của thanh niên chỉ là làm giàu thật nhanh cho bản thân và gia đình mình.", "Thanh niên chỉ cần lo học, việc xây dựng quê hương, đất nước là việc của người lớn.", "Góp sức vào sự nghiệp công nghiệp hoá, hiện đại hoá, xây dựng và bảo vệ Tổ quốc."], a: [true, false, false, true], x: "Thanh niên Việt Nam ngày nay phấn đấu có sức khoẻ, năng lực, bản lĩnh, làm người công dân tốt, góp sức công nghiệp hoá, hiện đại hoá, xây dựng và bảo vệ Tổ quốc. Lí tưởng ấy gắn lợi ích riêng với lợi ích của đất nước, không chỉ lo làm giàu cho riêng mình; thanh niên, kể cả học sinh, góp sức xây dựng quê hương ngay từ bây giờ.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Năm 1972, ông nội của Huy cùng nhiều bạn trẻ trong làng viết đơn xin nhập ngũ, lên đường chiến đấu. Hiện nay, anh trai của Huy là kĩ sư, cùng đồng nghiệp nghiên cứu giống lúa chịu mặn cho bà con vùng ven biển. Nhận xét nào về hai người là đúng?", o: ["Hai người sống ở hai thời kì khác nhau nhưng đều đặt sức mình vào việc chung của đất nước", "Chỉ ông nội của Huy mới có lí tưởng, vì thời bình thì không cần cống hiến cho đất nước", "Anh trai của Huy làm việc chỉ để có thu nhập, không liên quan gì tới lợi ích của bà con", "Cả hai người đều chỉ làm theo sở thích riêng của mình, không ai có mục đích sống cao đẹp"], x: "Thời chiến, nhiều thanh niên như ông nội của Huy cầm súng bảo vệ Tổ quốc; thời bình, nhiều người như anh trai của Huy dùng hiểu biết, nghề nghiệp của mình để giúp bà con, xây dựng đất nước. Cách cống hiến tuỳ hoàn cảnh, nhưng cả hai đều sống vì mục đích cao đẹp.", lv: 2 },
      { topic: "Sống có lí tưởng", type: "tf4", q: "Mỗi nhận xét sau về mục đích sống của các bạn đúng hay sai?", o: ["Quang ấp ủ viết một ứng dụng giúp bà con quê mình bán nông sản. Mục đích của Quang hướng tới lợi ích của mọi người.", "Hà chỉ mong có thật nhiều người theo dõi trên mạng xã hội để được nổi tiếng. Như vậy Hà đã có lí tưởng sống cao đẹp.", "Vinh muốn học ngành năng lượng để đưa điện mặt trời về những bản còn thiếu điện. Đó là một mục đích cao đẹp.", "Châu đặt mục tiêu đỗ trường chuyên và cho rằng chẳng cần quan tâm đến ai khác. Châu đang sống có lí tưởng."], a: [true, false, true, false], x: "Mục đích của Quang và Vinh gắn ước mơ của mình với lợi ích của bà con, quê hương nên là mục đích cao đẹp. Hà chỉ mong nổi tiếng cho bản thân; Châu chỉ nghĩ tới thành tích riêng, không quan tâm đến người khác, nên chưa phải sống có lí tưởng.", lv: 2 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Đầu năm học, Hào nói muốn làm ca sĩ; giữa năm, Hào lại muốn làm cầu thủ; cuối năm, Hào đổi sang muốn làm người mẫu. Hào chưa làm gì cho mong muốn nào cả. Nhận xét nào về Hào là đúng?", o: ["Hào chưa xác định được một mục đích lâu dài và chưa có hành động nào để thực hiện", "Hào là người có rất nhiều lí tưởng cao đẹp nên chắc chắn sẽ thành công", "Hào đã có một kế hoạch rõ ràng, cụ thể cho tương lai của bản thân mình", "Hào rất kiên định, luôn theo đuổi đến cùng mục tiêu mà mình đã chọn ngay từ đầu năm"], x: "Mong muốn của Hào đổi liên tục, lại chưa có việc làm nào để thực hiện, nên Hào chưa có mục đích lâu dài để phấn đấu. Nói về nhiều ước mơ không có nghĩa là đã có kế hoạch hay kiên định với mục tiêu.", lv: 2 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Tín ấp ủ ước mơ học ngành nông nghiệp công nghệ cao để giúp quê nhà làm giàu. Học hết lớp 9, Tín được một người quen rủ bỏ học, lên thành phố làm việc để có tiền ngay. Tín nên làm gì?", o: ["Cảm ơn nhưng từ chối, tiếp tục học để theo đuổi mục tiêu mình đã chọn", "Nhận lời ngay vì có tiền sớm quan trọng hơn mọi ước mơ của bản thân", "Bỏ học đi làm, hứa với bố mẹ khi nào có thật nhiều tiền sẽ đi học lại", "Để người quen quyết định thay mình vì người đó đã đi làm nhiều năm rồi"], x: "Ước mơ của Tín là mục đích tốt đẹp, gắn với quê hương. Tín nên giữ vững mục tiêu, tiếp tục học để có kiến thức thực hiện ước mơ. Bỏ học vì tiền trước mắt hay để người khác quyết định thay sẽ khiến Tín xa rời mục đích của mình.", lv: 3 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Yến mơ ước sau này làm cô giáo mầm non ở xã của mình. Một bạn chê: “Ước mơ gì mà nhỏ bé thế!”. Yến buồn, định giấu ước mơ đi. Nếu là bạn của Yến, em sẽ khuyên Yến điều gì?", o: ["Nghề nào giúp ích cho mọi người cũng đáng quý; Yến cứ vững tin và chăm học", "Yến nên chọn một nghề thật nổi tiếng để không bị ai chê bai thêm lần nào", "Yến nên kể ước mơ với thật nhiều người xem ai đồng tình nhiều hơn", "Yến nên chê lại ước mơ của bạn kia cho hai người cùng hoà, không ai hơn ai"], x: "Giá trị của một ước mơ không nằm ở chỗ nghề đó to hay nhỏ, nổi tiếng hay không, mà ở chỗ có ích cho mọi người. Dạy dỗ các em nhỏ ở quê là việc rất đáng quý; Yến nên tự tin, chăm học để thực hiện. Đổi ước mơ cho khỏi bị chê, đi hỏi ý mọi người hay chê lại bạn đều không giúp Yến.", lv: 3 },
      { topic: "Khoan dung", type: "mc", q: "Khoan dung có nghĩa là gì?", o: ["Rộng lòng tha thứ cho người đã nhận ra và sửa chữa lỗi lầm của mình", "Cho qua tất cả những sai phạm, kể cả khi người đó cố tình tái phạm", "Chấp nhận mọi việc làm của người khác để không ai phải phật lòng vì mình", "Im lặng, không bao giờ góp ý khi thấy người khác làm điều sai trái"], x: "Khoan dung là có tấm lòng rộng lượng, sẵn sàng tha thứ cho người đã biết hối hận, sửa lỗi. Khoan dung không phải là cho qua mọi sai phạm, chấp nhận mọi việc làm hay im lặng trước cái sai.", lv: 1 },
      { topic: "Khoan dung", type: "fill", q: "Thành ngữ “Chín bỏ làm ___” khuyên ta rộng lượng, sẵn lòng bỏ qua những thiếu sót nhỏ của người khác.", ans: ["mười"], x: "“Chín bỏ làm mười”: chín cũng coi như tròn mười, tức là không chấp nhặt những thiếu sót nhỏ, sống với nhau rộng rãi, dễ chịu.", lv: 1 },
      { topic: "Khoan dung", type: "mc", q: "Trong gia đình, cách cư xử nào sau đây cho thấy các thành viên biết khoan dung với nhau?", o: ["Anh chị em nhường nhịn, bỏ qua cho nhau những va chạm nhỏ hằng ngày", "Anh chị em tranh cãi đến cùng để phân rõ ai đúng, ai sai trong mọi chuyện", "Cha mẹ kể lại lỗi cũ của con với họ hàng mỗi khi có dịp gặp mặt", "Cả nhà làm ngơ khi một người đang buồn vì chuyện riêng của người đó"], x: "Trong gia đình, khoan dung là biết nhường nhịn, bỏ qua cho nhau những chuyện nhỏ để cả nhà hoà thuận. Tranh cãi hơn thua, kể lỗi cũ của nhau hay làm ngơ trước nỗi buồn của người thân đều làm gia đình kém gắn bó.", lv: 1 },
      { topic: "Khoan dung", type: "mc", q: "Việt Nam chủ trương “khép lại quá khứ, hướng tới tương lai”, sẵn sàng hợp tác với cả những nước từng gây chiến tranh trên đất nước mình. Chủ trương đó thể hiện điều gì?", o: ["Tinh thần rộng lượng, mong muốn hoà bình, hữu nghị giữa các dân tộc", "Việt Nam đã quên hết những mất mát, hi sinh trong các cuộc chiến tranh", "Việt Nam buộc phải hợp tác vì không có nước nào khác muốn làm bạn", "Việt Nam coi nhẹ lịch sử, không cần dạy truyền thống cho lớp trẻ nữa"], x: "“Khép lại quá khứ” không có nghĩa là quên lịch sử, mà là không để hận thù cản trở tương lai. Việt Nam rộng lượng, mong muốn hoà bình, hữu nghị và hợp tác cùng phát triển; nhân dân ta vẫn ghi nhớ, giáo dục truyền thống cho thế hệ sau.", lv: 2 },
      { topic: "Khoan dung", type: "tf4", q: "Mỗi nhận xét sau về cách ứng xử của từng bạn đúng hay sai?", o: ["Thấy Nhân ăn mặc giản dị, vài bạn trong lớp gọi Nhân là “nhà quê”. Các bạn ấy chưa tôn trọng người khác.", "Bà ngoại của Thu khó tính, hay nhắc nhở; Thu kiên nhẫn lắng nghe rồi nhẹ nhàng giải thích. Thu biết cảm thông với người thân.", "Từng bị một bạn ở lớp bên nói xấu, Cường không tin bất kì bạn nào của lớp đó nữa. Cách nghĩ của Cường là hợp lí.", "Bạn cùng bàn lỡ làm hỏng bút và đã xin lỗi, Lụa vẫn đòi bạn mua đền gấp đôi mới thôi giận. Lụa đã cư xử rộng lượng."], a: [true, true, false, false], x: "Chê bạn “nhà quê” vì cách ăn mặc là coi thường người khác. Thu lắng nghe, cảm thông với bà là biết bao dung với người thân. Cường đánh đồng cả lớp vì lỗi của một bạn là định kiến; Lụa chấp nhặt, đòi đền gấp đôi khi bạn đã xin lỗi là hẹp hòi.", lv: 2 },
      { topic: "Khoan dung", type: "mc", q: "Một bạn từng đăng bình luận chế giễu bức ảnh của Phương trên mạng. Sau đó, bạn ấy tự gỡ bình luận và nhắn tin xin lỗi chân thành. Phương nhận lời và vẫn chào hỏi bạn như trước. Việc làm của Phương cho thấy điều gì?", o: ["Phương sẵn lòng bỏ qua cho người đã thật lòng nhận ra lỗi của mình", "Phương sợ mâu thuẫn nên đành chấp nhận mọi việc làm của người khác", "Phương không coi trọng hình ảnh và danh dự của bản thân trên mạng", "Phương dễ dãi, sau này ai làm gì mình cũng không cần xin lỗi nữa"], x: "Bạn kia đã nhận ra cái sai, tự gỡ bình luận và xin lỗi chân thành, nên Phương nhận lời là biết tha thứ, giúp hai bạn giữ được quan hệ tốt. Đó không phải là sợ mâu thuẫn, dễ dãi hay coi nhẹ danh dự của mình.", lv: 2 },
      { topic: "Khoan dung", type: "mc", q: "Bạn thân của Hiền đã kể chuyện riêng của Hiền cho người khác nghe. Sau đó, bạn ấy rất hối hận, đến xin lỗi Hiền và hứa không bao giờ như vậy nữa. Hiền nên làm gì?", o: ["Nói cho bạn biết mình đã buồn ra sao, rồi nhận lời và cho bạn cơ hội sửa sai", "Kể lại chuyện riêng của bạn ấy cho người khác nghe để bạn hiểu cảm giác của mình", "Nhận lời cho xong chuyện nhưng từ nay không nói với bạn câu nào nữa", "Đòi bạn phải đứng trước cả lớp xin lỗi mình thì mới chịu bỏ qua"], x: "Bạn đã thật lòng hối hận và hứa sửa đổi, nên Hiền có thể nói rõ cảm xúc của mình để bạn hiểu, rồi tha thứ, cho bạn cơ hội làm lại. Trả đũa, giận ngầm hay bắt bạn xin lỗi trước cả lớp đều làm tình bạn thêm rạn nứt.", lv: 3 },
      { topic: "Khoan dung", type: "mc", q: "Năm lớp 8, Thịnh từng tự ý bỏ buổi biểu diễn làm đội văn nghệ của lớp bị trừ điểm thi đua. Năm nay, Thịnh đã chăm chỉ, đúng hẹn hơn và xin vào đội văn nghệ. Một số bạn phản đối. Là đội trưởng, Hậu nên làm gì?", o: ["Ghi nhận sự tiến bộ của Thịnh, nhận bạn vào đội và giao việc phù hợp", "Từ chối vì lỗi cũ năm lớp 8 của Thịnh vẫn còn đó, không thể bỏ qua", "Nhận Thịnh vào đội nhưng không giao việc gì để tránh rủi ro cho đội", "Bắt Thịnh xin lỗi từng bạn trong lớp rồi mới cho Thịnh vào đội văn nghệ"], x: "Thịnh đã nhận ra lỗi và thay đổi, nên Hậu nên ghi nhận, cho bạn cơ hội và giao việc vừa sức; Hậu cũng nên kể với các bạn còn phản đối về sự tiến bộ của Thịnh. Từ chối vì lỗi cũ, nhận cho có hay bắt xin lỗi từng người là thiếu rộng lượng.", lv: 3 },
      { topic: "Hoạt động cộng đồng", type: "match", q: "Nối mỗi hoạt động ở cột trái với nhóm hoạt động cộng đồng phù hợp ở cột phải.", l: ["Đi hiến máu cứu người tại điểm hiến máu của phường", "Góp tiền sửa nhà cho gia đình thương binh, liệt sĩ", "Tuyên truyền về tác hại của ma tuý cho thanh thiếu niên", "Cùng các cụ cao niên dạy trẻ em kéo co, đánh đu ở hội làng"], r: ["Thiện nguyện, nhân đạo", "Đền ơn đáp nghĩa", "Phòng, chống tệ nạn xã hội", "Gìn giữ và phát huy truyền thống văn hoá dân tộc", "Bảo vệ môi trường, cảnh quan"], x: "Hiến máu cứu người là hoạt động nhân đạo; giúp gia đình thương binh, liệt sĩ sửa nhà là đền ơn đáp nghĩa; tuyên truyền tác hại của ma tuý là phòng, chống tệ nạn xã hội; dạy trẻ kéo co, đánh đu ở hội làng là gìn giữ truyền thống văn hoá. Không hoạt động nào ở cột trái thuộc nhóm bảo vệ môi trường, cảnh quan.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Phong trào nào là phong trào chủ lực của Đoàn Thanh niên Cộng sản Hồ Chí Minh, gắn với những việc như chung tay xây dựng nông thôn mới, bảo vệ môi trường, chăm lo cho người khó khăn?", o: ["Thanh niên tình nguyện", "Kế hoạch nhỏ", "Nghìn việc tốt", "Đôi bạn cùng tiến"], x: "Theo văn kiện của Đoàn, “Thanh niên tình nguyện” là phong trào chủ lực, với các hoạt động như góp sức xây dựng nông thôn mới và đô thị văn minh, giữ trật tự an toàn giao thông, ứng phó với biến đổi khí hậu, chăm lo an sinh xã hội. “Kế hoạch nhỏ”, “Nghìn việc tốt” là phong trào của Đội Thiếu niên Tiền phong; “Đôi bạn cùng tiến” là phong trào giúp nhau học tập.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Cách làm nào sau đây là của người tích cực tham gia việc chung của cộng đồng?", o: ["Tự giác nhận phần việc vừa sức mình và làm đến nơi đến chốn", "Chỉ tham gia khi có bạn thân cùng đi và được chụp ảnh đăng lên mạng", "Đăng kí cho đủ số lượng rồi nhờ người khác làm thay phần việc của mình", "Hay chê bai việc chung nhưng không bao giờ góp sức hay góp ý cách làm"], x: "Người tích cực tự giác nhận việc phù hợp với sức mình và hoàn thành đến nơi đến chốn. Tham gia để chụp ảnh, đăng kí cho có hay chỉ chê bai đều là thiếu trách nhiệm với việc chung.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Đối với các hoạt động chung của địa phương, học sinh cần làm gì?", o: ["Chủ động tham gia và vận động người thân, bạn bè cùng góp sức", "Chỉ tham gia khi thầy cô bắt buộc và có ghi tên vào sổ theo dõi", "Để người lớn lo, học sinh chỉ cần học tốt các môn ở trường là đủ", "Chỉ tham gia những hoạt động mà mình được nhận quà hoặc tiền công"], x: "Hoạt động ở địa phương là việc chung, học sinh cũng là một thành viên: mình tham gia trước rồi rủ người thân, bạn bè cùng làm. Đợi bị bắt buộc, phó mặc cho người lớn hay chỉ làm khi có quà đều là thiếu trách nhiệm.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "tf4", q: "Mỗi nhận định sau về các hoạt động dưới đây đúng hay sai?", o: ["Một cửa hàng tặng nước uống kèm phiếu giảm giá để thu hút khách đến mua hàng. Đó là hoạt động thiện nguyện.", "Nhóm bạn của Bích dọn dẹp, trang trí lại nhà văn hoá thôn làm nơi sinh hoạt cho thiếu nhi. Đó là một hoạt động cộng đồng.", "Gia đình Bích tự sửa lại mái nhà của mình trước mùa mưa bão. Đó là một hoạt động cộng đồng.", "Thanh niên xã lập đội xung kích giúp bà con chằng chống nhà cửa trước bão. Đó là một hoạt động cộng đồng."], a: [false, true, false, true], x: "Nhà văn hoá cho thiếu nhi trong thôn và đội xung kích giúp bà con chống bão đem lại lợi ích cho nhiều người trong cộng đồng. Cửa hàng tặng nước kèm phiếu giảm giá là để bán được hàng; gia đình sửa nhà mình là việc riêng của gia đình.", lv: 2 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Khi thôn phát động góp ngày công làm đường bê tông, bố của Sinh nói: “Nhà mình ở cuối thôn, ít khi đi đường đó nên không cần góp sức.” Nhận xét nào sau đây là đúng?", o: ["Bố của Sinh chưa thấy con đường là lợi ích chung của cả thôn", "Bố của Sinh nghĩ đúng vì chỉ ai đi đường đó nhiều mới phải góp", "Việc làm đường là của chính quyền nên người dân không cần góp", "Ai góp nhiều ngày công sẽ được đi trên con đường đó nhiều hơn"], x: "Con đường bê tông phục vụ việc đi lại của cả thôn, cả khách đến thăm, xe chở hàng, nên nhà nào cũng nên góp sức. Nghĩ rằng ít đi thì không cần góp hay đẩy hết cho chính quyền là thờ ơ với việc chung.", lv: 2 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Con đường liên thôn nơi Kiên ở chưa có đèn, buổi tối đi lại rất nguy hiểm. Kiên muốn góp sức thay đổi điều đó. Cách làm nào phù hợp với lứa tuổi của Kiên?", o: ["Đề xuất với chi đoàn thôn vận động bà con cùng góp sức lắp đèn đường", "Tự trèo lên cột điện để nối dây lấy điện thắp sáng cho cả con đường", "Viết bài chê trách chính quyền trên mạng xã hội cho nhiều người biết", "Chờ đến khi đi làm, có thật nhiều tiền thì mới tự lắp đèn cho cả thôn"], x: "Kiên có thể nêu ý tưởng với chi đoàn thôn, cùng vận động bà con góp công, góp tiền lắp đèn: đó là cách góp sức vừa sức, an toàn. Tự nối điện rất nguy hiểm; chê trách trên mạng không giải quyết được việc; chờ đến khi có tiền là bỏ lỡ việc có thể làm ngay.", lv: 3 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Trên mạng có người kêu gọi chuyển tiền giúp một em bé bị bệnh nặng, nhưng không ghi rõ địa chỉ, người nhận. Mẹ của Hương xúc động, định chuyển tiền ngay. Hương nên khuyên mẹ điều gì?", o: ["Tìm hiểu kĩ thông tin, ủng hộ qua tổ chức, địa chỉ tin cậy", "Chuyển thật nhiều tiền ngay để em bé không phải chờ đợi thêm", "Chia sẻ bài kêu gọi cho mọi người rồi tự mình không ủng hộ nữa", "Từ nay không bao giờ tham gia ủng hộ bất kì ai nữa cho an toàn"], x: "Làm việc thiện cần đúng cách: tìm hiểu kĩ thông tin, gửi qua tổ chức, địa chỉ tin cậy để tấm lòng đến đúng người cần giúp và tránh bị lừa. Chuyển tiền vội, chỉ chia sẻ cho có hay từ đó không giúp ai nữa đều không phải cách làm phù hợp.", lv: 3 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Duyên được mời vào đội tình nguyện dạy hát cho các em nhỏ ở mái ấm tình thương vào chiều chủ nhật, nhưng sáng thứ hai có bài kiểm tra quan trọng. Duyên nên làm gì?", o: ["Ôn bài từ những ngày trước để chiều chủ nhật vẫn đi dạy hát được", "Bỏ buổi kiểm tra để dành trọn thời gian cho đội tình nguyện", "Nhận lời rồi không đến, vì đằng nào đội cũng đã có nhiều người", "Từ chối ngay, vì học sinh lớp 9 không nên tham gia thêm việc gì khác ngoài học"], x: "Duyên có thể sắp xếp ôn bài sớm để vừa học tốt vừa tham gia hoạt động có ý nghĩa với các em nhỏ. Bỏ kiểm tra, nhận lời rồi không đến hay từ chối mọi hoạt động đều không phải là cách cư xử có trách nhiệm.", lv: 3 }
    ]
  },
  "gdcd9-gk1-de2": {
    note: "Giáo dục công dân 9, sách Kết nối tri thức, giữa học kì I: Bài 1 Sống có lí tưởng; Bài 2 Khoan dung; Bài 3 Tích cực tham gia các hoạt động cộng đồng. Câu tình huống là chính. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Phạm vi của trường có thể khác, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu.",
    questions: [
      { topic: "Sống có lí tưởng", type: "mc", q: "Theo Điều lệ Đoàn Thanh niên Cộng sản Hồ Chí Minh, việc nào sau đây là nhiệm vụ của đoàn viên?", o: ["Chăm học, chăm làm, rèn luyện bản thân và góp sức vào các hoạt động xã hội", "Chỉ tham gia sinh hoạt Đoàn khi được nhắc nhở hoặc được khen thưởng", "Được miễn mọi việc chung của lớp để dành thời gian lo việc riêng", "Chỉ cần đóng đoàn phí đầy đủ hằng tháng, không phải tham gia thêm việc gì khác"], x: "Đoàn viên noi theo lí tưởng của Đảng, của Bác Hồ: chăm học, chăm làm, tự rèn luyện, tích cực tham gia các việc chung, góp sức cho quê hương, đất nước. Đóng đoàn phí chỉ là một việc nhỏ trong các nhiệm vụ; đoàn viên không được miễn việc chung.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Trong lời căn dặn thanh niên của Chủ tịch Hồ Chí Minh, đức tính “trung thành” được hiểu là gì?", o: ["Một lòng gắn bó suốt đời với Tổ quốc, với Đảng và sự nghiệp cách mạng", "Luôn nghe theo mọi lời bạn bè rủ rê, dù đó là việc đúng hay việc sai trái", "Chỉ giữ lời hứa với những người thân thiết trong gia đình của mình", "Giữ nguyên ý kiến của mình, không bao giờ chịu thay đổi trước ai cả"], x: "Bác Hồ dặn thanh niên phải trung thành: suốt đời một lòng với Tổ quốc, với Đảng và sự nghiệp cách mạng. Nghe theo mọi lời rủ rê, chỉ giữ lời với người thân hay khư khư giữ ý mình không phải là trung thành theo nghĩa đó.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Lối sống nào sau đây trái với sống có lí tưởng?", o: ["Buông thả, chạy theo thú vui trước mắt, không nghĩ đến tương lai", "Biết ơn, kính trọng những người đã hi sinh vì độc lập của Tổ quốc", "Luôn tìm cách dùng hiểu biết của mình để giúp ích cho mọi người", "Chăm chỉ học một nghề để sau này tự lập và giúp đỡ gia đình"], x: "Người sống buông thả, chỉ chạy theo thú vui trước mắt thì không có mục đích cao đẹp để phấn đấu. Biết ơn người đi trước, dùng hiểu biết giúp mọi người, chăm học nghề để tự lập đều là những việc làm đáng quý.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Trên mạng xã hội, một người viết: “Sống có lí tưởng là tự làm khổ mình, cứ sống cho bản thân là đủ.” Nhận xét nào về ý kiến đó là đúng?", o: ["Chưa đúng: sống vì mục đích tốt đẹp còn đem lại niềm vui, ý nghĩa cho chính mình", "Đúng: người sống có lí tưởng lúc nào cũng phải chịu khổ, không có niềm vui riêng", "Đúng: mỗi người chỉ nên lo cho bản thân, việc chung đã có người khác lo", "Chưa đúng: sống có lí tưởng là không bao giờ gặp khó khăn, vất vả nào cả"], x: "Người sống có lí tưởng có thể vất vả, nhưng họ thấy việc mình làm có ích nên sống vui và có ý nghĩa. Chỉ sống cho bản thân dễ khiến con người ích kỉ; có lí tưởng cũng không có nghĩa là tránh được mọi khó khăn.", lv: 2 },
      { topic: "Sống có lí tưởng", type: "tf4", q: "Mỗi ý sau về việc làm của những người trẻ dưới đây đúng hay sai?", o: ["Chị Như vào đội tình nguyện chỉ để có ảnh đẹp đăng lên mạng. Chị Như tham gia vì muốn phục vụ cộng đồng.", "Anh Khoa cùng nhóm bạn chế tạo máy sấy nông sản chạy bằng năng lượng mặt trời, giúp bà con giảm hư hỏng sau thu hoạch. Việc làm đó có ích cho nhiều người.", "Chị Mai là kĩ sư công nghệ thông tin, cuối tuần dạy lập trình miễn phí cho học sinh vùng khó. Chị dùng hiểu biết của mình để giúp người khác.", "Muốn thực hiện lí tưởng thì phải đợi đến khi có thật nhiều tiền."], a: [false, true, true, false], x: "Anh Khoa, chị Mai dùng hiểu biết của mình để giúp bà con, học sinh: đó là cách người trẻ hôm nay sống có lí tưởng. Chị Như tham gia vì muốn có ảnh đẹp, không vì người khác. Thực hiện lí tưởng không cần chờ giàu có.", lv: 2 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Tuấn Anh muốn làm bác sĩ vì nghề này được nhiều người kính nể và có thu nhập cao. Minh Khôi cũng muốn làm bác sĩ để về chữa bệnh cho bà con vùng sâu, vùng xa đang thiếu thầy thuốc. Nhận xét nào sau đây là đúng?", o: ["Cùng một nghề, nhưng mục đích của Minh Khôi gắn với lợi ích của nhiều người hơn", "Hai bạn có lí tưởng giống hệt nhau vì cùng muốn sau này làm bác sĩ", "Mục đích của Tuấn Anh cao đẹp hơn vì nghề bác sĩ luôn được rất nhiều người kính nể", "Muốn có thu nhập cao là sai, nên Tuấn Anh không được chọn nghề bác sĩ"], x: "Hai bạn cùng chọn một nghề nhưng khác nhau ở mục đích: Minh Khôi nghĩ tới những người đang cần mình, nên mục đích ấy cao đẹp hơn. Mong có thu nhập cao không có gì sai, chỉ là chưa gắn với lợi ích của cộng đồng.", lv: 2 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Thanh mơ ước trở thành cán bộ khí tượng để dự báo bão, giúp bà con vùng biển quê mình tránh thiệt hại. Bố mẹ Thanh lại muốn Thanh học ngành ngân hàng cho ổn định. Thanh nên làm gì?", o: ["Trình bày với bố mẹ về ước mơ, lí do và cùng tìm hiểu thêm về ngành học", "Im lặng làm theo ý bố mẹ dù bản thân không hề thích ngành học đó chút nào", "Giận dỗi, bỏ ăn cho đến khi bố mẹ đồng ý theo ý mình mới thôi", "Bỏ cả hai ngành, chọn đại một ngành mà bạn bè đang thi vào nhiều"], x: "Thanh nên bình tĩnh chia sẻ với bố mẹ về ước mơ và ý nghĩa của nghề khí tượng, cùng tìm hiểu thông tin để cả nhà hiểu nhau. Im lặng làm theo, giận dỗi hay chọn đại theo bạn bè đều không giúp Thanh thực hiện mục đích tốt đẹp của mình.", lv: 3 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Chi đoàn lớp 9A kêu gọi đoàn viên đăng kí kèm cặp các bạn học còn yếu. Hưng học giỏi Toán nhưng ngại mất thời gian ôn thi vào lớp 10. Hưng nên làm gì?", o: ["Nhận kèm một bạn, sắp xếp thời gian để vừa ôn thi vừa giúp bạn tiến bộ", "Không đăng kí vì việc kèm bạn chỉ làm mất thời gian ôn thi vào lớp 10 của mình", "Đăng kí cho có tên rồi để bạn tự học, không cần hướng dẫn gì thêm", "Đòi bạn được kèm phải trả tiền thì mới đồng ý giúp bạn học Toán"], x: "Giúp bạn học là việc làm của người đoàn viên có trách nhiệm; giảng lại cho bạn cũng giúp Hưng nắm chắc kiến thức hơn. Hưng chỉ cần sắp xếp thời gian hợp lí. Từ chối, đăng kí cho có hay đòi tiền đều đi ngược tinh thần giúp đỡ người khác của người đoàn viên.", lv: 3 },
      { topic: "Khoan dung", type: "mc", q: "Từ nào sau đây gần nghĩa nhất với “khoan dung”?", o: ["Độ lượng", "Cần cù", "Thật thà", "Khiêm tốn"], x: "“Độ lượng” là rộng rãi, dễ tha thứ, gần nghĩa với khoan dung. “Cần cù” nói về sự chăm chỉ; “thật thà” là ngay thẳng, không dối trá; “khiêm tốn” là không tự đề cao mình.", lv: 1 },
      { topic: "Khoan dung", type: "mc", q: "Biểu hiện nào sau đây là thiếu khoan dung?", o: ["Hẹp hòi, hay chấp nhặt và khó bỏ qua cho người khác", "Lắng nghe người khác nói hết rồi mới nêu ý kiến của mình", "Cảm thông với người mắc lỗi vì hoàn cảnh khó khăn", "Vui vẻ làm quen với bạn mới chuyển đến lớp mình"], x: "Hẹp hòi, chấp nhặt, khó bỏ qua cho người khác là thiếu khoan dung. Lắng nghe, cảm thông, cởi mở với người khác là biểu hiện của tấm lòng rộng mở.", lv: 1 },
      { topic: "Khoan dung", type: "mc", q: "Câu nào sau đây nói đúng về lòng khoan dung của người Việt Nam?", o: ["Là nét đẹp có từ lâu đời, thể hiện qua cách đối xử giữa người với người", "Là thói quen mới chỉ xuất hiện ở nước ta trong vài năm gần đây", "Chỉ cần có ở người lớn tuổi, còn học sinh thì chưa cần rèn luyện", "Chỉ thể hiện với người thân trong gia đình, không cần với người ngoài xã hội"], x: "Khoan dung là một nét đẹp trong truyền thống văn hoá lâu đời của dân tộc, thể hiện trong cách con người cư xử với nhau ở gia đình, trường học, ngoài xã hội. Ai cũng cần rèn luyện, kể cả học sinh.", lv: 1 },
      { topic: "Khoan dung", type: "mc", q: "Bảo Ngọc thích nghe nhạc cổ điển, trong khi cả nhóm bạn thích nhạc trẻ. Vài bạn hay trêu Ngọc là “bà cụ non” trước mặt cả lớp. Nhận xét nào về các bạn là đúng?", o: ["Các bạn chưa biết chấp nhận sở thích khác mình của Ngọc", "Các bạn đúng, vì Ngọc cần thích những gì cả nhóm thích", "Các bạn chỉ đùa vui, việc đó không ảnh hưởng gì tới Ngọc", "Ngọc có lỗi vì đã chọn một sở thích khác với số đông"], x: "Mỗi người có sở thích riêng; trêu chọc Ngọc trước lớp vì Ngọc thích nhạc cổ điển là thiếu tôn trọng sự khác biệt, có thể làm Ngọc tổn thương. Ngọc không có lỗi khi có sở thích khác các bạn.", lv: 2 },
      { topic: "Khoan dung", type: "tf4", q: "Mỗi nhận xét sau về cách ứng xử của các bạn đúng hay sai?", o: ["Thấy em làm vỡ cốc rồi giấu đi, Hạ mắng em thật to và kể với cả xóm cho em xấu hổ. Hạ đang giúp em sửa lỗi đúng cách.", "Trong giờ thảo luận, Tâm Anh luôn cắt ngang khi bạn nói khác ý mình. Tâm Anh biết lắng nghe, tôn trọng người khác.", "Một bạn lớp bên từng làm hỏng mô hình của nhóm Lâm. Khi bạn ấy cần người giúp sửa xe đạp, Lâm vẫn vui vẻ giúp. Lâm cư xử rộng lượng.", "Ông của Long hay kể đi kể lại chuyện cũ; Long vẫn ngồi nghe và trò chuyện vui vẻ cùng ông. Long biết cảm thông với ông."], a: [false, false, true, true], x: "Mắng to, kể với cả xóm khiến em xấu hổ, sợ hãi chứ không giúp em biết nhận lỗi. Cắt ngang khi bạn nói khác ý mình là chưa biết lắng nghe. Lâm không để bụng chuyện cũ; Long kiên nhẫn, cảm thông với ông: đó là những cách cư xử rộng lượng.", lv: 2 },
      { topic: "Khoan dung", type: "mc", q: "Sau một lần cãi nhau, Trung chủ động nhắn tin làm lành với Đức. Đức nghĩ: “Ai làm lành trước là người thua.” Nhận xét nào về suy nghĩ của Đức là đúng?", o: ["Chưa đúng: Trung chủ động làm lành vì biết trân trọng tình bạn", "Đúng: người làm lành trước là người chịu nhận mình sai hoàn toàn", "Đúng: Trung làm lành trước vì sợ bị cả lớp xa lánh mà thôi", "Chưa đúng: lẽ ra Trung phải chờ Đức làm lành trước mới đúng"], x: "Chủ động làm lành không phải là thua hay nhận hết phần sai, mà là biết đặt tình bạn lên trên chuyện hơn thua: đó là biểu hiện của lòng rộng lượng. Đức nên đáp lại thiện chí của Trung.", lv: 2 },
      { topic: "Khoan dung", type: "mc", q: "Một bạn du học sinh nước ngoài đến giao lưu với lớp và vô tình có cử chỉ mà ở nước ta bị coi là thiếu lịch sự. Vài bạn trong lớp tỏ ra khó chịu, xì xào. Là lớp trưởng, Minh Anh nên làm gì?", o: ["Giải thích rằng mỗi nước có thói quen riêng, rồi tế nhị chia sẻ với bạn ấy", "Nói ngay với bạn du học sinh rằng bạn ấy thật bất lịch sự trước cả lớp", "Để các bạn tiếp tục xì xào cho bạn du học sinh tự nhận ra lỗi của mình", "Đề nghị thầy cô từ nay không mời bạn du học sinh đến giao lưu với lớp mình nữa"], x: "Cử chỉ của bạn du học sinh chỉ là do khác thói quen, không cố ý. Minh Anh nên giúp các bạn hiểu rằng mỗi dân tộc có phong tục riêng, cần tôn trọng điều đó, đồng thời nhẹ nhàng giới thiệu phép lịch sự của người Việt cho bạn. Chê trách trước lớp, để mọi người xì xào hay không mời bạn nữa đều thiếu tôn trọng khách.", lv: 3 },
      { topic: "Khoan dung", type: "mc", q: "Trong giờ thuyết trình, Toản bị nói lắp nên vài bạn ngồi cạnh em bật cười, chỉ trỏ. Em nên làm gì?", o: ["Nhắc các bạn giữ trật tự, tôn trọng Toản, rồi khích lệ Toản nói tiếp", "Cười theo các bạn cho vui, vì Toản cũng đã quen bị các bạn trêu như vậy rồi", "Ngồi im, làm như không biết gì, vì việc đó không liên quan đến mình", "Đề nghị cô giáo cho Toản thôi thuyết trình để Toản đỡ ngượng"], x: "Chế giễu khuyết điểm của người khác là thiếu tôn trọng, làm bạn tổn thương. Em nên nhắc các bạn và động viên Toản. Cười theo, làm ngơ hay để Toản thôi thuyết trình đều không giúp gì cho bạn.", lv: 3 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Hoạt động nào sau đây thuộc nhóm phòng, chống tệ nạn xã hội?", o: ["Vận động bà con trong xóm không đánh bạc, không cá độ bóng đá", "Quyên góp tiền mua áo phao tặng học sinh vùng sông nước", "Thăm hỏi, chăm sóc các cựu chiến binh neo đơn ở địa phương", "Phục dựng điệu múa cổ trong lễ hội truyền thống của làng mình hằng năm"], x: "Đánh bạc, cá độ là tệ nạn xã hội, nên vận động bà con tránh xa là phòng, chống tệ nạn. Tặng áo phao là thiện nguyện; chăm sóc cựu chiến binh là đền ơn đáp nghĩa; phục dựng múa cổ là gìn giữ văn hoá truyền thống.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "tf4", q: "Mỗi ý sau về nhóm hoạt động cộng đồng của các việc làm dưới đây đúng hay sai?", o: ["Tổ chức hội thi gói bánh chưng ngày Tết ở khu dân cư là hoạt động gìn giữ truyền thống văn hoá.", "Cùng bố mẹ đi du lịch ở một bãi biển đẹp là hoạt động bảo vệ môi trường, cảnh quan.", "Bán hàng qua mạng giúp cửa hàng của gia đình là một hoạt động cộng đồng.", "Mở lớp xoá mù chữ cho người lớn tuổi chưa biết chữ là hoạt động thiện nguyện."], a: [true, false, false, true], x: "Hội thi gói bánh chưng giữ gìn phong tục ngày Tết; lớp xoá mù chữ giúp người lớn tuổi biết đọc, biết viết là việc thiện nguyện. Đi du lịch cùng gia đình, bán hàng cho cửa hàng nhà mình là việc riêng, không phải hoạt động cộng đồng.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Thành ngữ nào sau đây nói về tinh thần mà các hoạt động cộng đồng khơi dậy ở mỗi người?", o: ["Tương thân tương ái", "Ăn cháo đá bát", "Đứng núi này trông núi nọ", "Nước đổ lá khoai"], x: "“Tương thân tương ái” là thương yêu, giúp đỡ lẫn nhau: đó là tinh thần mà các hoạt động cộng đồng khơi dậy và lan rộng. “Ăn cháo đá bát” chê kẻ vô ơn; “Đứng núi này trông núi nọ” chê người không bằng lòng với cái mình có; “Nước đổ lá khoai” nói lời khuyên không có tác dụng.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Việc làm nào sau đây là hoạt động cộng đồng góp phần bảo đảm an toàn giao thông?", o: ["Cùng đội thanh niên hướng dẫn các em nhỏ qua đường ở cổng trường", "Tự đi xe đạp đúng phần đường của mình mỗi ngày khi đến trường", "Mua một chiếc mũ bảo hiểm mới thật đẹp để đội khi đi xe máy", "Rủ các bạn đi xe đạp hàng ba, hàng bốn cho vui trên đường làng mỗi chiều"], x: "Hướng dẫn các em nhỏ qua đường ở cổng trường là việc làm vì người khác, góp phần giữ an toàn giao thông: đó là hoạt động cộng đồng. Đi đúng phần đường, đội mũ bảo hiểm là việc mỗi người phải tự làm; đi xe hàng ba, hàng bốn là vi phạm.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "tf4", q: "Mỗi nhận xét sau về các bạn đúng hay sai?", o: ["Tùng xin nghỉ buổi tổng vệ sinh của phường vì hôm đó phải đi khám bệnh. Tùng thờ ơ với việc chung.", "Ly tranh thủ tối thứ bảy đọc sách cho các cụ ở trung tâm dưỡng lão, dù chẳng ai yêu cầu. Ly có tinh thần tự giác.", "Nhóm của Khang làm xong phần việc được giao rồi còn ở lại giúp các nhóm khác. Nhóm Khang làm việc có trách nhiệm.", "Thấy vài bạn vứt rác xuống mương, Nguyên nghĩ đó không phải việc của mình nên làm ngơ. Nguyên đã cư xử đúng."], a: [false, true, true, false], x: "Tùng có lí do chính đáng nên không phải là thờ ơ. Ly tự giác đến với các cụ; nhóm Khang làm xong việc của mình còn giúp nhóm khác: đều là những cách tham gia tích cực. Làm ngơ trước việc làm sai ảnh hưởng tới môi trường chung như Nguyên là thiếu trách nhiệm.", lv: 2 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Thấy đoàn cứu hộ đang chuyển hàng cứu trợ qua đoạn nước lũ chảy xiết, Thắng (học sinh lớp 9) định lội theo để giúp. Nhận xét nào về Thắng là đúng?", o: ["Thắng có ý tốt nhưng nên chọn việc an toàn, vừa sức như phân loại hàng cứu trợ", "Thắng làm đúng, vì càng nhiều người cùng lội nước thì hàng cứu trợ càng đến nhanh", "Thắng nên ở nhà vì học sinh không được làm bất cứ việc gì giúp vùng lũ", "Thắng sai vì giúp đỡ người bị lũ lụt chỉ là việc của đoàn cứu hộ"], x: "Mong muốn giúp đỡ của Thắng là đáng quý, nhưng lội qua nước lũ chảy xiết rất nguy hiểm. Học sinh nên chọn việc phù hợp lứa tuổi, an toàn như phân loại, đóng gói hàng cứu trợ, để không trở thành người cần được cứu.", lv: 2 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Khi Lực nhặt rác ở công viên gần nhà, vài bạn trêu Lực là “làm màu”. Lực nên làm gì?", o: ["Vẫn tiếp tục làm, bình tĩnh giải thích lợi ích của việc giữ công viên sạch", "Thôi không nhặt rác nữa để khỏi bị các bạn trêu chọc thêm bất kì lần nào nữa", "Cãi nhau với các bạn rồi đăng ảnh các bạn lên mạng để chê lại", "Chỉ nhặt rác vào lúc không có ai nhìn thấy để khỏi bị trêu chọc"], x: "Việc Lực làm có ích cho mọi người nên Lực cứ tiếp tục, bình tĩnh giải thích để các bạn hiểu. Bỏ việc tốt vì bị trêu, cãi nhau hay làm lén đều không cần thiết, còn bỏ lỡ cơ hội giúp các bạn thay đổi suy nghĩ.", lv: 3 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Làng của Tiến có đội múa sư tử truyền thống nhưng ngày càng ít người trẻ tham gia, các nghệ nhân lo đội sẽ mai một. Tiến khá nhanh nhẹn, có năng khiếu. Tiến nên làm gì?", o: ["Đăng kí học múa với các nghệ nhân để góp phần giữ nét đẹp của làng", "Chờ các nghệ nhân tự tìm người khác vì việc đó không liên quan tới mình", "Chê múa sư tử là lạc hậu, rủ các bạn chuyển sang học nhảy hiện đại", "Chỉ quay video các nghệ nhân múa để đăng lên mạng lấy lượt xem"], x: "Đội múa sư tử là nét đẹp văn hoá của làng; Tiến tham gia học múa là góp sức gìn giữ truyền thống. Phó mặc, chê bai hay chỉ quay video lấy lượt xem đều không giúp đội múa tiếp tục.", lv: 3 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Đoàn phường tìm tình nguyện viên hướng dẫn các cụ ở câu lạc bộ người cao tuổi dùng điện thoại để gọi video cho con cháu ở xa. Vĩ dùng điện thoại thành thạo nhưng ngại nói chuyện với người lớn tuổi. Vĩ nên làm gì?", o: ["Đăng kí tham gia, chuẩn bị trước cách hướng dẫn đơn giản, dễ nhớ", "Không đăng kí vì người lớn tuổi khó học, có hướng dẫn cũng vô ích", "Đăng kí nhưng chỉ ngồi làm hộ, không hướng dẫn để các cụ tự làm", "Chỉ hướng dẫn những cụ là ông bà của mình, người khác thì thôi"], x: "Vĩ có hiểu biết phù hợp với việc cần giúp, nên đăng kí và chuẩn bị cách hướng dẫn dễ hiểu; tham gia cũng giúp Vĩ mạnh dạn, rèn kĩ năng giao tiếp. Từ chối, làm hộ hay chỉ giúp người nhà mình đều chưa đúng tinh thần của hoạt động.", lv: 3 }
    ]
  },
  /* ---------- GDCD 9 · Kiểm tra cuối học kì I (Kết nối tri thức; Phiên N9-ck1-lsdl-gdcd) ----------
     Sách Giáo dục công dân 9 in năm 2026 (OnUp-Book lop-9/giao-duc-cong-dan-9), Bài 1–6: Sống có lí tưởng; Khoan dung; Tích cực
     tham gia các hoạt động cộng đồng; Khách quan và công bằng; Bảo vệ hoà bình; Quản lí thời gian hiệu quả. Câu tự soạn: tình huống,
     nhân vật, câu tục ngữ không lấy từ sách (nhân vật của sách mang tên một chữ cái), không dùng lại các nhận định của phần Luyện tập.
     Hai đề là kho của đề ngẫu nhiên "gdcd9-ck1-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận ở
     data/banks/index.js). Mỗi đề 25 câu chia đúng ma trận 10 Biết, 8 Hiểu, 7 Vận dụng: Bài 1–5 mỗi bài 4 câu, Bài 6 5 câu; ô rút 2
     câu có 4 câu (mỗi đề 2 câu), nên hai câu cùng ô cũng không ghi sẵn đáp án của nhau. Cách xếp mức như GDCD 6: nêu khái niệm, ý
     nghĩa, câu tục ngữ, biểu hiện là Biết; nhận ra phẩm chất qua việc làm của một bạn, đánh giá nhận định, giải thích vì sao là Hiểu;
     xử lí tình huống, sắp xếp công việc, tính thời gian là Vận dụng. Chữ chủ đề Bài 3 rút gọn thành “Hoạt động cộng đồng”.
     tests/lsdl-gdcd9-ck1.js tính lại hai câu tính thời gian của Bài 6. */
  "gdcd9-ck1-de1": {
    note: "Giáo dục công dân 9, sách Kết nối tri thức, học kì I: Bài 1 Sống có lí tưởng; Bài 2 Khoan dung; Bài 3 Tích cực tham gia các hoạt động cộng đồng; Bài 4 Khách quan và công bằng; Bài 5 Bảo vệ hoà bình; Bài 6 Quản lí thời gian hiệu quả. Câu tình huống là chính. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Phạm vi của trường có thể khác, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 9; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Sống có lí tưởng", type: "mc", q: "Ý nào sau đây nói đúng về sống có lí tưởng?", o: ["Xác định mục đích tốt đẹp, có kế hoạch và quyết tâm thực hiện để góp sức cho đất nước", "Làm theo mọi việc người khác chọn cho mình, không cần suy nghĩ về tương lai", "Cố gắng đạt mọi mục tiêu của bản thân bằng bất cứ cách nào, kể cả những cách làm sai trái", "Sống thoải mái theo ý thích, không cần đặt ra mục tiêu cho tương lai"], x: "Sống có lí tưởng là biết chọn cho mình một mục đích tốt đẹp, lập kế hoạch và quyết tâm thực hiện, để vừa thành công vừa góp sức cho cộng đồng, đất nước. Đạt mục tiêu bằng cách sai trái, sống không mục tiêu hay để người khác chọn hộ đều không phải là sống có lí tưởng.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Sống có lí tưởng mang lại điều gì cho mỗi người?", o: ["Giúp có động lực vượt qua khó khăn, được mọi người tôn trọng, tin tưởng", "Giúp không bao giờ gặp thất bại hay khó khăn nào trong học tập và cuộc sống", "Giúp được người khác làm thay những việc khó của mình", "Giúp trở nên giàu có ngay mà không cần phải cố gắng"], x: "Lí tưởng sống là động lực giúp mỗi người phấn đấu, vượt khó để hoàn thành mục tiêu, góp phần xây dựng đất nước; người như vậy được mọi người ghi nhận, quý trọng, tin tưởng. Sống có lí tưởng vẫn có thể gặp khó khăn, thất bại, nhưng biết cách vượt qua.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Bạn nào dưới đây là người sống có lí tưởng?", o: ["Khánh muốn sau này về dạy học ở bản mình nên ngày nào cũng chăm học, đọc thêm sách", "Duy muốn sau này thật giàu để chỉ việc ăn chơi, không phải làm việc gì cả", "Thảo nói muốn làm nhà khoa học nhưng chưa bao giờ chịu khó học bài, làm thí nghiệm ở lớp", "Kha đặt mục tiêu đứng đầu lớp bằng mọi cách, kể cả quay cóp khi kiểm tra"], x: "Khánh mong được dạy học cho các em ở bản mình và chăm học mỗi ngày để làm được điều đó. Duy chỉ nghĩ cho bản thân; Thảo có ước mơ nhưng không cố gắng; Kha chọn cách sai trái để đạt mục tiêu.", lv: 2 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Lan mơ ước trở thành kĩ sư nông nghiệp để giúp bà con quê mình trồng trọt hiệu quả hơn, nhưng Lan học chưa tốt môn Sinh học, lại hay nản khi gặp bài khó. Lan nên làm gì?", o: ["Nhờ thầy cô chỉ cách học, đặt mục tiêu từng tuần, kiên trì khi gặp bài khó", "Bỏ ước mơ đó, chọn một nghề khác vì nghĩ mình không có năng khiếu với môn Sinh học", "Chờ lên lớp 10 rồi mới bắt đầu cố gắng học tốt môn Sinh học", "Chỉ học môn Sinh học, bỏ qua hết các môn học khác cho đỡ mệt"], x: "Muốn đạt ước mơ, Lan cần biến ước mơ thành kế hoạch cụ thể và kiên trì thực hiện: tìm cách học phù hợp, đặt mục tiêu nhỏ cho từng tuần, không nản khi gặp khó. Bỏ cuộc, trì hoãn hay học lệch đều không giúp Lan đạt được mục đích.", lv: 3 },
      { topic: "Khoan dung", type: "mc", q: "Biểu hiện nào sau đây thể hiện lòng khoan dung?", o: ["Lắng nghe, tôn trọng những ý kiến khác mình, không định kiến với người khác", "Nhớ mãi lỗi nhỏ của bạn để nhắc lại mỗi khi hai người cãi nhau", "Chỉ chơi thân với những bạn có cùng sở thích, cùng ý kiến, cùng hoàn cảnh với mình", "Muốn mọi người trong nhóm phải làm theo ý mình thì mới vui vẻ"], x: "Người khoan dung biết lắng nghe ý kiến khác mình, không giữ thành kiến với ai. Nhắc mãi lỗi cũ, chỉ chơi với người giống mình, bắt người khác theo ý mình là thiếu khoan dung.", lv: 1 },
      { topic: "Khoan dung", type: "mc", q: "Người có lòng khoan dung thường nhận được điều gì?", o: ["Được mọi người quý mến, tin tưởng, gắn bó", "Bị mọi người coi thường vì tính quá dễ dãi", "Luôn phải chịu thiệt thòi, không được ai quý mến", "Khiến người mắc lỗi càng mắc thêm nhiều lỗi hơn"], x: "Người khoan dung được mọi người quý mến, tin tưởng; người mắc lỗi được tha thứ cũng có dịp sửa mình; mọi người sống với nhau hoà thuận hơn. Khoan dung không phải là dễ dãi hay bỏ qua cái sai.", lv: 1 },
      { topic: "Khoan dung", type: "tf4", q: "Mỗi ý sau nhận xét về cách cư xử của các bạn đúng hay sai?", o: ["Tâm từng bị điểm kém một lần nên Ngân không muốn học nhóm với Tâm. Ngân đang có định kiến với bạn.", "Bảo lỡ nói nặng lời với em, đã xin lỗi và sửa đổi nhưng vẫn tự trách mãi. Bảo cần biết tha thứ cho chính mình.", "Sơn bắt chước giọng nói của bạn mới đến từ vùng khác để trêu cả lớp. Đó chỉ là trò đùa, không phải thiếu tôn trọng bạn.", "Khải góp ý thẳng thắn khi bạn thân quay cóp. Như vậy là Khải thiếu khoan dung với bạn."], a: [true, true, false, false], x: "a), b) Đúng: đánh giá bạn chỉ qua một lần điểm kém là định kiến; khi đã nhận lỗi và sửa chữa, ta cũng cần tha thứ cho chính mình. c), d) Sai: trêu chọc giọng nói vùng miền là thiếu tôn trọng sự khác biệt; khoan dung không có nghĩa là bỏ qua cái sai, góp ý để bạn sửa là việc làm đúng.", lv: 2 },
      { topic: "Khoan dung", type: "mc", q: "Trong trận bóng giao hữu, Đạt vô tình đá trúng chân Toàn làm Toàn phải nghỉ tập một tuần. Đạt đã đến xin lỗi, hỏi thăm Toàn. Toàn nên làm gì?", o: ["Nhận lời xin lỗi, coi đó là sự cố và vẫn chơi thân với Đạt", "Đề nghị cả đội không cho Đạt chơi bóng cùng nữa", "Nhận lời cho qua chuyện nhưng chờ dịp đá trả lại Đạt cho hả giận", "Không nhận lời, từ nay không nói chuyện với Đạt"], x: "Đạt vô tình gây ra chuyện và đã biết nhận lỗi, nên Toàn cần rộng lòng tha thứ, giữ tình bạn. Trả đũa, xa lánh hay đòi cả đội tẩy chay Đạt là thiếu khoan dung, làm tình bạn rạn nứt.", lv: 3 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Hoạt động nào sau đây thuộc nhóm hoạt động đền ơn đáp nghĩa?", o: ["Thăm hỏi, tặng quà các gia đình thương binh, liệt sĩ", "Trồng cây xanh, dọn rác dọc đường làng", "Quyên góp sách vở, quần áo ấm cho học sinh vùng bị lũ lụt", "Tập hát dân ca để biểu diễn trong lễ hội làng"], x: "Thăm hỏi, tặng quà gia đình thương binh, liệt sĩ, người có công là hoạt động đền ơn đáp nghĩa. Trồng cây, dọn rác là bảo vệ môi trường; quyên góp cho vùng lũ là hoạt động thiện nguyện, nhân đạo; tập hát dân ca cho lễ hội là gìn giữ truyền thống văn hoá.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Tích cực tham gia các hoạt động cộng đồng giúp học sinh:", o: ["Mở rộng hiểu biết, rèn kĩ năng và tinh thần trách nhiệm", "Được miễn tham gia các hoạt động học tập ở trường", "Được cộng thêm điểm vào tất cả các môn học", "Không cần quan tâm đến việc của gia đình nữa"], x: "Tham gia hoạt động cộng đồng giúp mỗi người hiểu biết rộng hơn, rèn thêm kĩ năng sống, tinh thần trách nhiệm, được mọi người yêu mến. Hoạt động cộng đồng không thay cho việc học, việc nhà, cũng không phải để được cộng điểm.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Bạn nào dưới đây đã tích cực tham gia hoạt động cộng đồng?", o: ["Thư thường cùng chi đoàn khu phố đến thăm, giúp đỡ các cụ già neo đơn", "Tuấn đăng kí dọn vệ sinh đường làng nhưng đến nơi lại ngồi chơi điện thoại", "Linh chỉ tham gia việc chung khi được thầy cô hứa cộng điểm thi đua", "Hoà cho rằng việc chung là của người lớn nên không bao giờ tham gia"], x: "Thư chủ động, thường xuyên tham gia hoạt động giúp đỡ người già neo đơn ở nơi mình sống. Tuấn chỉ đăng kí cho có; Linh tham gia vì được cộng điểm; Hoà thờ ơ với việc chung.", lv: 2 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Xã của Nga tổ chức buổi trồng cây, dọn rác ven kênh vào sáng chủ nhật. Bạn của Nga ngại nắng, rủ Nga ở nhà chơi trò chơi điện tử. Nga nên làm gì?", o: ["Nói cho bạn hiểu ích lợi của buổi lao động và rủ bạn cùng đi, mang theo mũ", "Ở nhà chơi cùng bạn vì nghĩ buổi lao động đã có rất nhiều người khác tham gia rồi", "Đi một mình và từ nay không chơi với người bạn lười biếng ấy nữa", "Đến điểm danh cho có mặt rồi lặng lẽ về nhà chơi với bạn"], x: "Nga nên tham gia và vận động bạn cùng tham gia, chuẩn bị mũ, nước uống để không ngại nắng. Ở nhà, đến cho có hay giận dỗi bỏ bạn đều không giúp được việc chung, cũng không giúp bạn thay đổi.", lv: 3 },
      { topic: "Khách quan và công bằng", type: "mc", q: "Người có thái độ khách quan khi nhìn nhận một sự việc là người:", o: ["Xem xét sự việc đúng như nó vốn có, không để tình cảm riêng chi phối", "Kết luận theo điều mình mong muốn, dù chưa rõ đúng sai", "Chỉ tin vào lời kể của những người mà mình yêu quý, tin tưởng từ trước đến nay", "Đánh giá thật nhanh theo ấn tượng ban đầu về sự việc đó"], x: "Người khách quan nhìn sự việc đúng như nó vốn có, trung thực, không để tình cảm, định kiến chi phối. Kết luận theo mong muốn, chỉ nghe người mình quý hay theo ấn tượng ban đầu dễ dẫn đến đánh giá sai.", lv: 1 },
      { topic: "Khách quan và công bằng", type: "mc", q: "Bạn nào dưới đây đã có cách nhìn nhận khách quan?", o: ["Đọc bài viết chê một điểm du lịch, Phúc tìm thêm thông tin ở nhiều nguồn rồi mới nhận xét", "Thấy Tài từng nghịch ngợm, Đức khẳng định với cả lớp rằng chắc chắn Tài đã làm vỡ cửa kính", "Ý Nhi tin ngay lời kể của bạn thân mà không hỏi lại những người có mặt", "Lộc chỉ đọc tiêu đề một bản tin rồi chia sẻ kèm lời bình luận gay gắt"], x: "Phúc không vội tin một bài viết mà tìm hiểu thêm từ nhiều nguồn trước khi nhận xét: đó là cách nhìn nhận khách quan. Đức có định kiến với Tài; Ý Nhi thiên vị bạn thân; Lộc vội kết luận khi chưa đọc hết thông tin.", lv: 2 },
      { topic: "Khách quan và công bằng", type: "tf4", q: "Mỗi việc làm sau thể hiện sự công bằng đúng hay sai?", o: ["Để chọn bạn đi thi kể chuyện, cô cho cả lớp thi vòng loại với cùng một cách chấm.", "Đội trưởng Kiên chỉ cho các bạn thân vào sân, các bạn khác dù tập chăm vẫn phải ngồi ngoài.", "Chủ cửa hàng cân đủ cho khách quen, còn khách lạ thì cân thiếu đi một chút.", "Cô giáo dành thêm thời gian kèm bạn mới chuyển đến đang học chậm để bạn theo kịp lớp."], a: [true, false, false, true], x: "a), d) Đúng: ai cũng được thi và chấm như nhau; bạn đang gặp khó khăn được giúp thêm để có cơ hội phát triển như các bạn khác. b), c) Sai: chỉ ưu ái bạn thân, khách quen là thiên vị, phân biệt đối xử.", lv: 2 },
      { topic: "Khách quan và công bằng", type: "mc", q: "Tổ của Hằng được thưởng một hộp bút màu vì làm tốt dự án. Có bạn đề nghị chia nhiều hơn cho các bạn thân của tổ trưởng. Hằng nên đề xuất cách chia nào?", o: ["Chia theo mức đóng góp mà cả tổ đã cùng nhận xét, thống nhất", "Để tổ trưởng tự quyết, bạn nào thân thì được nhiều hơn", "Chia hết cho các bạn hay được cô khen trong lớp", "Không chia, để cả hộp bút cho tổ trưởng giữ riêng"], x: "Phần thưởng là của cả tổ, nên chia dựa trên mức đóng góp mà mọi người đã cùng nhìn nhận, thống nhất: ai cũng được xét theo cùng một tiêu chí. Ưu ái bạn thân hay để một người giữ hết là thiếu công bằng.", lv: 3 },
      { topic: "Bảo vệ hoà bình", type: "mc", q: "Biểu hiện nào sau đây cho thấy một đất nước đang có hoà bình?", o: ["Trẻ em được đến trường, người lớn yên tâm làm việc", "Các nhóm vũ trang thường xuyên giao tranh trên đường phố", "Nhiều trẻ em phải nghỉ học để đi lánh nạn", "Nhiều gia đình phải sống trong các trại tị nạn"], x: "Ở đất nước có hoà bình, không có súng đạn, giao tranh; mọi người yên ổn đi học, đi làm, cùng xây dựng cuộc sống. Giao tranh, lánh nạn, sống trong trại tị nạn là cảnh của nơi có chiến tranh, xung đột.", lv: 1 },
      { topic: "Bảo vệ hoà bình", type: "mc", q: "Khi hai quốc gia có tranh chấp, cách giải quyết nào góp phần bảo vệ hoà bình?", o: ["Thương lượng, đàm phán trên cơ sở luật pháp quốc tế", "Tăng cường chạy đua vũ trang để răn đe nước kia", "Cắt đứt mọi quan hệ, không hợp tác với nước kia nữa", "Nhờ một nước lớn đem quân đến can thiệp"], x: "Mâu thuẫn, tranh chấp giữa các quốc gia cần được giải quyết bằng biện pháp hoà bình: thương lượng, đàm phán, dựa vào luật pháp quốc tế, công lí. Chạy đua vũ trang, cắt quan hệ hay nhờ nước khác đem quân đến dễ đẩy tranh chấp thành xung đột.", lv: 1 },
      { topic: "Bảo vệ hoà bình", type: "mc", q: "Lớp 9C từng hay cãi vã vì những chuyện nhỏ. Từ khi cả lớp hẹn nhau nói năng ôn tồn, biết nhường nhịn nhau, lớp ít mâu thuẫn hẳn, các bạn gắn bó hơn. Câu chuyện của lớp 9C cho thấy điều gì?", o: ["Cách cư xử hằng ngày của mỗi người cũng góp phần giữ gìn sự bình yên", "Chỉ thầy cô mới giải quyết được mâu thuẫn giữa các học sinh", "Muốn lớp ít mâu thuẫn thì không bạn nào được nêu ý kiến riêng của mình nữa", "Chuyện cãi vã trong lớp học không liên quan gì đến hoà bình"], x: "Hoà bình bắt đầu từ những mối quan hệ gần gũi: nói năng ôn tồn, nhường nhịn nhau giúp lớp học yên vui, ít mâu thuẫn; nhiều người cư xử như vậy thì cộng đồng, xã hội cũng bình yên hơn. Lớp 9C tự làm được điều đó mà không bạn nào phải bỏ ý kiến riêng của mình.", lv: 2 },
      { topic: "Bảo vệ hoà bình", type: "mc", q: "Giờ ra chơi, hai bạn lớp bên tranh cãi gay gắt vì va vào nhau ở sân bóng, có bạn còn định đánh nhau. Nếu chứng kiến, em nên làm gì?", o: ["Can ngăn, khuyên hai bạn bình tĩnh, nhờ thầy cô giúp đỡ", "Đứng xem rồi cổ vũ cho bạn mà mình quen biết hơn", "Lặng lẽ bỏ đi chỗ khác vì đó không phải việc của mình", "Rủ thêm vài bạn đến giúp một bên cho đủ sức"], x: "Thấy bạn sắp xô xát, em nên chủ động can ngăn, khuyên các bạn bình tĩnh nói chuyện để hiểu nhau; nếu không được thì báo ngay thầy cô. Cổ vũ, bỏ đi hay giúp một bên đều có thể làm mâu thuẫn lớn hơn.", lv: 3 },
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Quản lí thời gian hiệu quả giúp mỗi người:", o: ["Chủ động trong công việc, giảm áp lực, làm việc năng suất hơn", "Không bao giờ phải dành thời gian để nghỉ ngơi, giải trí", "Làm xong được mọi việc mà không cần lập kế hoạch nào", "Lúc nào cũng hoàn thành công việc nhanh hơn mọi người"], x: "Biết sắp xếp, dùng thời gian hợp lí giúp ta chủ động, làm việc có năng suất, hiệu quả, giảm áp lực, có thêm động lực và ngày càng tiến bộ. Quản lí thời gian tốt vẫn cần dành thời gian nghỉ ngơi.", lv: 1 },
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Bạn nào dưới đây đã biết quản lí thời gian hiệu quả?", o: ["Mỗi tối, Diệp ghi lại các việc cần làm, đặt giờ cho từng việc, học xong mới xem phim", "Phương lập thời gian biểu rất đẹp, dán trên bàn học nhưng hầu như không làm theo", "Quý ngồi vào bàn học rồi mới đi tìm sách vở, bút thước, mất gần nửa giờ", "Lâm đang học Toán lại chuyển sang vẽ, rồi quay về Toán, việc gì cũng dở dang"], x: "Diệp biết lên danh sách việc cần làm, phân bổ thời gian cho từng việc và giữ đúng kế hoạch. Phương có kế hoạch nhưng không thực hiện; Quý không chuẩn bị trước nên mất thời gian; Lâm thiếu tập trung, việc gì cũng dở dang.", lv: 2 },
      { topic: "Quản lí thời gian hiệu quả", type: "tf4", q: "Mỗi ý sau về cách quản lí thời gian đúng hay sai?", o: ["Biết rõ mục tiêu, thời hạn của từng việc là bước đầu tiên khi quản lí thời gian.", "Kế hoạch đã lập thì phải giữ nguyên, kể cả khi có việc đột xuất hay bị ốm.", "Cất điện thoại ra xa khi học giúp hạn chế những thứ gây sao nhãng.", "Chỉ người lớn đi làm mới cần quản lí thời gian, học sinh thì chưa cần."], a: [true, false, true, false], x: "a), c) Đúng: trước tiên cần xác định các việc phải làm và thời hạn của từng việc; khi học nên tránh xa những thứ gây sao nhãng như điện thoại. b), d) Sai: kế hoạch cần được điều chỉnh khi có thay đổi đột xuất hay khi sức khoẻ không tốt; học sinh cũng cần biết quản lí thời gian để học tập, rèn luyện hiệu quả.", lv: 2 },
      { topic: "Quản lí thời gian hiệu quả", type: "num", q: "Tối nay, Vy có từ 19 giờ đến 22 giờ để học bài và làm việc nhà. Vy dự định: làm bài tập Toán 50 phút, ôn bài Ngữ văn 40 phút, giúp mẹ rửa bát 15 phút, nghỉ giải lao hai lần, mỗi lần 10 phút. Nếu làm đúng kế hoạch, Vy còn bao nhiêu phút để đọc sách trước 22 giờ?", ans: 55, unit: "phút", x: "Từ 19 giờ đến 22 giờ có 3 × 60 = 180 (phút). Các việc dự định mất 50 + 40 + 15 + 2 × 10 = 125 (phút). Thời gian còn lại để đọc sách là 180 − 125 = 55 (phút).", lv: 3 },
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Tuần tới, Minh Anh có bài kiểm tra Toán vào thứ Ba, phải nộp bài thu hoạch Lịch sử vào thứ Năm và được mời dự sinh nhật bạn vào tối thứ Hai. Cách sắp xếp nào hợp lí nhất?", o: ["Ôn Toán từ cuối tuần này, dự sinh nhật về sớm, sau thứ Ba làm bài thu hoạch", "Dự sinh nhật đến thật khuya rồi sáng thứ Ba dậy sớm để ôn bài Toán", "Làm bài thu hoạch trước, đến tối thứ Hai mới bắt đầu ôn Toán", "Bỏ dự sinh nhật, thức thật khuya tối thứ Hai để làm xong cả bài ôn lẫn bài thu hoạch"], x: "Bài kiểm tra Toán đến trước nên cần ôn sớm, chia ra nhiều buổi; vẫn có thể dự sinh nhật nhưng về sớm để giữ sức khoẻ; sau thứ Ba còn đủ thời gian làm bài thu hoạch nộp vào thứ Năm. Thức khuya hay dồn việc vào phút cuối đều làm giảm hiệu quả.", lv: 3 }
    ]
  },

  /* Đề 2 (Phiên N9-ck1-lsdl-gdcd): cùng phạm vi, cùng chủ đề và mức từng câu như đề 1 (ma trận của đề ngẫu nhiên), mỗi câu hỏi một ý
     khác các câu cùng ô của đề 1. Có một câu điền (câu tục ngữ về việc không trì hoãn) và một câu tính thời gian (Bài 6). */
  "gdcd9-ck1-de2": {
    note: "Giáo dục công dân 9, sách Kết nối tri thức, học kì I: Bài 1 Sống có lí tưởng; Bài 2 Khoan dung; Bài 3 Tích cực tham gia các hoạt động cộng đồng; Bài 4 Khách quan và công bằng; Bài 5 Bảo vệ hoà bình; Bài 6 Quản lí thời gian hiệu quả. Câu tình huống là chính. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Phạm vi của trường có thể khác, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 9; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Sống có lí tưởng", type: "mc", q: "Thanh niên Việt Nam ngày nay sống có lí tưởng là phấn đấu cho mục tiêu nào?", o: ["Độc lập dân tộc và chủ nghĩa xã hội, vì một Việt Nam giàu mạnh, văn minh", "Làm giàu cho bản thân bằng mọi cách, không cần quan tâm đến người khác", "Ra nước ngoài sinh sống, không cần gắn bó với quê hương", "Chỉ lo học thật giỏi, không cần rèn luyện sức khoẻ, đạo đức"], x: "Mục tiêu của thanh niên Việt Nam ngày nay là giữ vững độc lập dân tộc, xây dựng chủ nghĩa xã hội, góp sức bảo vệ và xây dựng Tổ quốc, đưa đất nước ngày càng giàu mạnh, văn minh.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Để thực hiện lí tưởng sống, học sinh cần làm gì?", o: ["Chăm học, giữ gìn sức khoẻ, hăng hái góp sức vào việc chung của lớp, trường", "Chờ học xong đại học mới bắt đầu nghĩ đến mục tiêu của mình", "Chỉ cần học thật giỏi các môn thi vào lớp 10, không cần tham gia việc chung của lớp", "Để bố mẹ quyết định thay mình mọi mục tiêu cho tương lai"], x: "Học sinh thực hiện lí tưởng sống qua những việc hằng ngày: chăm học, chăm làm, rèn luyện thân thể, tham gia hoạt động tập thể, giúp ích cho cộng đồng. Chờ đợi, học lệch hay phó mặc cho người khác đều không giúp thực hiện lí tưởng.", lv: 1 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Anh Dũng tốt nghiệp đại học loại giỏi, từ chối một công việc lương cao ở thành phố để về quê mở hợp tác xã trồng rau sạch, tạo việc làm cho bà con. Việc làm của anh Dũng cho thấy điều gì?", o: ["Anh có mục đích tốt đẹp, gắn thành công của mình với lợi ích quê hương", "Anh không đủ năng lực để làm những công việc ở thành phố lớn", "Anh chỉ muốn làm giàu thật nhanh cho riêng bản thân mình mà thôi", "Anh thiếu ý chí phấn đấu nên chọn về quê làm một công việc nhẹ nhàng, ít áp lực hơn"], x: "Anh Dũng chọn về quê làm việc để góp sức cho bà con, quê hương: anh đặt thành công của mình bên cạnh lợi ích của mọi người. Anh về quê không phải vì thiếu năng lực hay ý chí; trồng rau sạch cũng không phải việc nhẹ nhàng.", lv: 2 },
      { topic: "Sống có lí tưởng", type: "mc", q: "Trong giờ sinh hoạt lớp, Phong nói: “Bàn chuyện lí tưởng là xa vời, học sinh lớp 9 chỉ cần vui chơi cho thoải mái.” Nếu là bạn cùng lớp, em nên làm gì?", o: ["Giải thích cho Phong hiểu và rủ Phong cùng đặt mục tiêu học tập", "Đồng tình vì học sinh lớp 9 còn nhỏ, chưa cần nghĩ đến tương lai", "Chê bai, chế giễu Phong trước cả lớp để Phong thấy xấu hổ", "Im lặng vì đó là suy nghĩ riêng, không liên quan đến mình"], x: "Em nên góp ý nhẹ nhàng: lí tưởng không xa vời mà bắt đầu từ những việc hằng ngày như học tập, rèn luyện, giúp đỡ mọi người; rồi rủ Phong cùng đặt mục tiêu, lập kế hoạch học tập. Đồng tình, chế giễu hay im lặng đều không giúp được bạn.", lv: 3 },
      { topic: "Khoan dung", type: "mc", q: "Câu tục ngữ nào sau đây khuyên con người sống khoan dung?", o: ["Đánh kẻ chạy đi, không ai đánh người chạy lại", "Ăn quả nhớ kẻ trồng cây", "Có công mài sắt, có ngày nên kim", "Một cây làm chẳng nên non, ba cây chụm lại nên hòn núi cao"], x: "“Đánh kẻ chạy đi, không ai đánh người chạy lại”: người đã biết lỗi, quay lại nhận lỗi thì nên được tha thứ. “Ăn quả nhớ kẻ trồng cây” nói về lòng biết ơn; “Có công mài sắt, có ngày nên kim” nói về sự kiên trì; câu cuối nói về tinh thần đoàn kết.", lv: 1 },
      { topic: "Khoan dung", type: "mc", q: "Để rèn luyện lòng khoan dung, mỗi người cần:", o: ["Cư xử chân thành, rộng lượng, tôn trọng nét riêng của mỗi người", "Giữ khoảng cách với những người có tính cách khác mình", "Ghi nhớ lỗi của người khác để biết đường tránh xa họ", "Luôn nhận hết phần sai về mình, kể cả khi người khác mới là người sai"], x: "Muốn rèn lòng khoan dung, mỗi người nên đối xử chân thành, rộng lượng, biết quý nét riêng của người khác, tránh thói ích kỉ, hẹp hòi. Khoan dung không có nghĩa là nhận phần sai về mình hay bỏ qua cái sai.", lv: 1 },
      { topic: "Khoan dung", type: "mc", q: "Bố mẹ dặn Quân: “Tha thứ cho bạn không có nghĩa là bỏ qua cái sai của bạn.” Lời dặn đó có ý nghĩa gì?", o: ["Tha thứ cho người đã biết lỗi nhưng vẫn góp ý để họ sửa", "Người đã mắc lỗi thì không cần phải sửa chữa nữa", "Không bao giờ nên tha thứ cho người đã từng mắc lỗi", "Người mắc lỗi phải bị phạt thật nặng thì mới nhớ"], x: "Người khoan dung sẵn lòng tha thứ, nhưng không bao che, dung túng cái sai: ta vẫn góp ý để người mắc lỗi nhận ra và sửa chữa. Không tha thứ hay phạt thật nặng là thiếu khoan dung; bỏ qua mà không giúp bạn sửa thì bạn dễ mắc lỗi lần nữa.", lv: 2 },
      { topic: "Khoan dung", type: "mc", q: "Nhóm của Vân được giao làm báo tường. Ý tưởng của Bách khác hẳn ý tưởng của cả nhóm, nên vài bạn không muốn nghe Bách trình bày. Là nhóm trưởng, Vân nên làm gì?", o: ["Đề nghị cả nhóm nghe hết ý tưởng của Bách rồi cùng bàn bạc, lựa chọn", "Gạt ngay ý tưởng của Bách đi để cả nhóm làm cho nhanh xong việc", "Báo cô giáo để cô cho Bách chuyển sang làm cùng một nhóm khác hợp ý bạn ấy hơn", "Để Bách tự làm riêng một tờ báo tường theo ý của bạn ấy"], x: "Nghe hết ý tưởng của Bách rồi cùng bàn, nhóm có thêm cách làm hay, Bách thấy mình được tôn trọng, cả nhóm đoàn kết hơn. Gạt đi, đẩy bạn sang nhóm khác hay để bạn làm riêng đều khiến bạn tổn thương, nhóm mất đoàn kết.", lv: 3 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Hoạt động nào sau đây là hoạt động cộng đồng?", o: ["Đoàn thanh niên xã mở lớp dạy bơi miễn phí cho trẻ em trong dịp hè", "Cả nhà Minh cùng nhau đi du lịch biển vào dịp nghỉ hè năm nay", "Nam ở nhà tự luyện đàn mỗi buổi tối để thi vào trường nghệ thuật", "Hai chị em Thu cùng nhau dọn dẹp, trang trí phòng riêng của mình"], x: "Lớp dạy bơi miễn phí do Đoàn thanh niên xã tổ chức đem lại lợi ích chung cho trẻ em, gia đình trong xã: đó là hoạt động cộng đồng. Các việc còn lại là việc riêng của cá nhân, gia đình.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Đối với cộng đồng, các hoạt động cộng đồng có ý nghĩa gì?", o: ["Gắn kết mọi người, lan toả lòng nhân ái và tinh thần đoàn kết", "Giúp mỗi gia đình không còn phải lo việc riêng của mình", "Thay thế hoàn toàn mọi công việc mà chính quyền địa phương phải làm", "Chỉ đem lại lợi ích cho người đứng ra tổ chức hoạt động"], x: "Hoạt động cộng đồng huy động sức mạnh của nhiều người, kết nối các thành viên, lan toả sự đoàn kết, nhân ái và những giá trị tốt đẹp. Hoạt động đó không thay việc riêng của mỗi nhà hay việc của chính quyền.", lv: 1 },
      { topic: "Hoạt động cộng đồng", type: "tf4", q: "Mỗi ý sau về hoạt động cộng đồng đúng hay sai?", o: ["Học sinh còn nhỏ tuổi thì chưa thể tham gia hoạt động cộng đồng.", "Một nhóm học sinh cũng có thể tự tổ chức hoạt động cộng đồng, không nhất thiết phải chờ chính quyền.", "Chỉ cần một vài người tham gia là đủ, người khác không cần quan tâm đến việc chung.", "Thờ ơ trước những việc chung của khu dân cư là biểu hiện thiếu trách nhiệm."], a: [false, true, false, true], x: "b), d) Đúng: cá nhân, tập thể nào cũng có thể đứng ra tổ chức hoạt động vì lợi ích chung, nên một nhóm học sinh cũng làm được; thờ ơ với việc chung là thiếu trách nhiệm, cần phê phán. a), c) Sai: học sinh tham gia được nhiều hoạt động vừa sức; việc chung cần nhiều người cùng góp sức.", lv: 2 },
      { topic: "Hoạt động cộng đồng", type: "mc", q: "Trường của Khôi kêu gọi quyên góp sách cho thư viện của một trường ở vùng cao. Khôi có nhiều sách truyện đã đọc xong. Khôi nên làm gì?", o: ["Chọn những cuốn còn tốt để ủng hộ, rủ thêm các bạn cùng góp sách", "Chỉ góp những cuốn đã rách, mất trang vì đằng nào cũng cho đi", "Không góp cuốn nào vì sách đã mua là đồ dùng của riêng mình", "Mang sách cũ đi bán lấy tiền để mua thêm đồ chơi mới"], x: "Khôi nên chọn sách còn đẹp, phù hợp với các bạn nhỏ để ủng hộ và vận động bạn bè cùng góp, để thư viện vùng cao có thêm nhiều sách hay. Góp sách rách, không góp hay đem bán đều không đúng với tinh thần tham gia hoạt động cộng đồng.", lv: 3 },
      { topic: "Khách quan và công bằng", type: "mc", q: "Người đối xử công bằng với mọi người là người:", o: ["Đối xử với mọi người theo cùng một lẽ phải, không thiên vị ai", "Ưu tiên những người thân quen trước, còn người lạ thì để lại sau cùng", "Chỉ quan tâm đến quyền lợi của bản thân mình", "Đối xử tốt với người giàu có, có địa vị hơn mình"], x: "Người công bằng đối xử như nhau với mọi người theo lẽ phải, không thiên vị người này hay coi nhẹ người kia; nhờ đó không ai bị thiệt thòi, ai cũng được tôn trọng. Ưu tiên người quen, chỉ lo cho mình hay nể người có địa vị là thiếu công bằng.", lv: 1 },
      { topic: "Khách quan và công bằng", type: "mc", q: "Khi tự đánh giá cuối học kì, Duyên chỉ ghi những việc mình làm tốt, còn mấy lần quên làm bài tập, đi học muộn thì bỏ qua không ghi. Nhận xét nào về cách tự đánh giá của Duyên là đúng?", o: ["Chưa khách quan, vì Duyên mới nêu phần tốt, chưa nêu phần chưa tốt", "Đã khách quan, vì những việc tốt Duyên ghi đều là việc có thật", "Đã khách quan, vì tự đánh giá là việc riêng, ghi thế nào cũng được", "Chưa khách quan, vì Duyên phải nhờ bạn thân đánh giá thay mình"], x: "Tự đánh giá khách quan là nhìn nhận cả việc mình làm tốt lẫn việc chưa tốt, để biết mình cần sửa gì. Duyên mới ghi phần tốt nên bản tự đánh giá chưa đúng với thực tế, dù các việc tốt đó là có thật. Duyên vẫn tự đánh giá được, chỉ cần ghi trung thực cả hai phần.", lv: 2 },
      { topic: "Khách quan và công bằng", type: "mc", q: "Ở hội thi kéo co của khối 9, bạn làm trọng tài là học sinh lớp 9A. Bạn ấy bỏ qua lỗi giẫm vạch của đội 9A nhưng lại bắt lỗi rất chặt đội 9B. Cách làm đó dễ dẫn đến điều gì?", o: ["Đội 9B thấy bất bình, hai lớp dễ xích mích với nhau", "Đội 9B sẽ cố gắng hơn để được trọng tài ưu ái", "Không ảnh hưởng gì vì kéo co chỉ là trò chơi", "Hai lớp sẽ tin tưởng bạn trọng tài ấy hơn trước"], x: "Bắt lỗi hai đội không như nhau là thiên vị: đội bị thiệt thấy bất bình, mất lòng tin vào trọng tài, hai lớp dễ nảy sinh mâu thuẫn. Dù chỉ là trò chơi, cách làm đó vẫn làm tổn thương người khác; trọng tài cần xử lí lỗi của hai đội như nhau.", lv: 2 },
      { topic: "Khách quan và công bằng", type: "mc", q: "Hai bạn trong lớp cãi nhau, một bên là bạn thân của em. Cô chủ nhiệm nhờ em kể lại sự việc. Em nên làm gì?", o: ["Kể đúng những gì mình đã thấy, không thêm bớt để bênh bạn thân", "Kể theo hướng có lợi cho bạn thân để bạn ấy không bị cô phê bình, phạt", "Nói không biết gì để khỏi mất lòng bạn nào", "Chỉ kể những lỗi của bạn kia, giấu lỗi của bạn mình"], x: "Kể trung thực, đúng như sự việc đã xảy ra giúp cô hiểu rõ đúng sai để giải quyết hợp lí: đó là thái độ khách quan, công bằng. Bênh bạn thân, giấu lỗi hay im lặng đều làm cô khó đánh giá đúng sự việc.", lv: 3 },
      { topic: "Bảo vệ hoà bình", type: "mc", q: "Vì sao các quốc gia cần cùng nhau bảo vệ hoà bình?", o: ["Để các nước cùng phát triển, sống hữu nghị, hợp tác với nhau", "Để các nước lớn dễ dàng chi phối, áp đặt ý muốn lên các nước nhỏ hơn", "Để mỗi nước không cần giao lưu với các nước khác", "Để không còn phải xây dựng lực lượng bảo vệ Tổ quốc"], x: "Hoà bình đem lại cuộc sống bình yên, ấm no, hạnh phúc; ngăn chặn chiến tranh thì các nước mới phát triển kinh tế – xã hội, sống hữu nghị, cùng hợp tác với nhau. Bảo vệ hoà bình vẫn cần xây dựng, bảo vệ Tổ quốc vững mạnh.", lv: 1 },
      { topic: "Bảo vệ hoà bình", type: "mc", q: "Việc làm nào sau đây của học sinh thể hiện thái độ phản đối chiến tranh phi nghĩa?", o: ["Tham gia quyên góp giúp đỡ trẻ em ở những nơi bị chiến tranh tàn phá", "Chia sẻ lên mạng những đoạn phim cổ vũ cho hành động xâm lược nước khác", "Cho rằng chiến tranh ở nước khác không liên quan gì đến mình", "Rủ các em nhỏ chơi trò bắn súng, đánh trận suốt cả ngày"], x: "Quyên góp giúp đỡ nạn nhân chiến tranh, lên án chiến tranh phi nghĩa, tham gia các phong trào ủng hộ hoà bình là những việc học sinh làm được. Cổ vũ xâm lược hay thờ ơ trước chiến tranh là trái với lòng yêu chuộng hoà bình.", lv: 1 },
      { topic: "Bảo vệ hoà bình", type: "tf4", q: "Mỗi ý sau về bảo vệ hoà bình đúng hay sai?", o: ["Chỉ khi đất nước có chiến tranh, người dân mới cần quan tâm đến việc giữ gìn hoà bình.", "Thoả hiệp với mọi việc làm sai trái để tránh xung đột là cách giữ gìn hoà bình đúng đắn.", "Giữ gìn hoà bình là trách nhiệm của mọi người, không riêng gì của các nhà lãnh đạo.", "Chiến tranh, xung đột vũ trang ở một nước có thể gây khó khăn cho người dân ở nhiều nước khác."], a: [false, false, true, true], x: "c), d) Đúng: ai cũng góp phần giữ gìn hoà bình từ những việc làm hằng ngày; chiến tranh, xung đột ở một nơi có thể làm nhiều nước bị ảnh hưởng (người tị nạn, giá cả, kinh tế). a), b) Sai: hoà bình cần được giữ gìn cả khi đất nước đang yên ổn; giữ gìn hoà bình không có nghĩa là nhân nhượng với cái sai, cái ác.", lv: 2 },
      { topic: "Bảo vệ hoà bình", type: "mc", q: "Trường của Thanh giao lưu trực tuyến với một trường ở nước bạn. Một bạn trong lớp định nói đùa chê bai món ăn, trang phục của nước bạn. Thanh nên làm gì?", o: ["Nhắc bạn tôn trọng văn hoá của nước bạn, không nói lời chê bai", "Hùa theo bạn để buổi giao lưu thêm vui, thêm sôi nổi", "Im lặng, để bạn ấy tự chịu trách nhiệm về những lời nói đùa của mình", "Xin rời khỏi buổi giao lưu để mình khỏi bị liên lụy"], x: "Tôn trọng, không kì thị văn hoá của các dân tộc, quốc gia khác là việc học sinh có thể làm để góp phần giữ gìn hoà bình, hữu nghị. Thanh nên nhắc bạn và cùng bạn chuẩn bị những lời giới thiệu, câu hỏi thân thiện. Hùa theo, im lặng hay bỏ đi đều không ngăn được lời nói gây tổn thương.", lv: 3 },
      { topic: "Quản lí thời gian hiệu quả", type: "fill", q: "Hoàn thành câu tục ngữ khuyên không nên trì hoãn công việc: “Việc hôm nay chớ để ngày ___.”", ans: ["mai"], x: "“Việc hôm nay chớ để ngày mai”: việc gì làm được hôm nay thì làm ngay, đừng để dồn lại, vì để lâu việc chồng chất, dễ bị lỡ thời hạn.", lv: 1 },
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Tuần trước khi thi, tối nào Tâm cũng học đến quá nửa đêm, bỏ cả giờ ăn tối và giờ chơi thể thao. Đến hôm thi, Tâm mệt mỏi, khó tập trung. Vì sao như vậy?", o: ["Tâm chưa dành thời gian hợp lí cho ăn uống, nghỉ ngơi, vận động", "Tâm học chưa đủ nhiều, lẽ ra phải học thêm cả buổi sáng và giờ nghỉ trưa", "Tâm ôn bài quá sớm nên đến hôm thi đã quên gần hết", "Bài thi khó hơn nhiều so với những gì Tâm đã ôn"], x: "Học liền nhiều giờ, bỏ bữa, thiếu ngủ, không vận động khiến Tâm kiệt sức, đầu óc không còn tỉnh táo, nên học nhiều mà kết quả không như mong muốn. Khi lập kế hoạch, cần dành thời gian cân đối cho học tập, ăn uống, nghỉ ngơi và vận động.", lv: 2 },
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Thói quen nào sau đây khiến việc quản lí thời gian kém hiệu quả?", o: ["Nhận quá nhiều việc cùng lúc, vượt quá khả năng của mình", "Viết những việc quan trọng lên giấy nhớ dán ở bàn học", "Đi ngủ và thức dậy vào một giờ cố định mỗi ngày", "Làm bài khó vào lúc mình tỉnh táo nhất trong ngày"], x: "Ôm đồm nhiều việc vượt quá khả năng khiến việc nào cũng dở dang, dễ quá tải, mệt mỏi. Ba thói quen còn lại đều giúp làm việc hiệu quả hơn.", lv: 2 },
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Đầu kì nghỉ hè, Hiếu muốn học bơi, đọc hết 5 cuốn sách và giúp bố mẹ bán hàng, nhưng tuần đầu tiên chưa làm được việc nào. Hiếu nên làm gì?", o: ["Ghi rõ mục tiêu từng việc, đặt giờ cố định mỗi ngày, cuối tuần tự xem lại", "Bỏ hết các dự định vì kì nghỉ hè là để vui chơi thoải mái", "Chờ đến tháng cuối của kì nghỉ, khi đã chơi đủ, rồi mới làm cả ba việc một lúc", "Chỉ cần nhớ các dự định trong đầu, không cần ghi ra kế hoạch"], x: "Hiếu cần xác định rõ mục tiêu (học bơi mấy buổi, đọc mấy trang sách mỗi ngày, giúp bố mẹ lúc nào), xây dựng kế hoạch với giờ cố định, rồi tự giác thực hiện và xem lại để điều chỉnh. Bỏ cuộc, dồn việc đến cuối kì nghỉ hay không ghi kế hoạch đều dễ khiến dự định không thành.", lv: 3 },
      { topic: "Quản lí thời gian hiệu quả", type: "num", q: "Mỗi ngày, Vinh dành 40 phút xem video giải trí trên điện thoại. Nếu bớt một nửa thời gian đó để đọc sách, sau 30 ngày, Vinh có thêm bao nhiêu giờ đọc sách?", ans: 10, unit: "giờ", x: "Mỗi ngày Vinh có thêm 40 : 2 = 20 (phút) đọc sách. Sau 30 ngày: 20 × 30 = 600 (phút), tức là 600 : 60 = 10 (giờ).", lv: 3 }
    ]
  },
  /* ---------- GDCD 9 · Kiểm tra giữa học kì II (Kết nối tri thức; Bài 7–8 và ôn Bài 6; Phiên N9-gk2-lsdl-gdcd) ----------
     Sách Giáo dục công dân 9 in năm 2026 (OnUp-Book lop-9/giao-duc-cong-dan-9): Bài 7 Thích ứng với thay đổi, Bài 8 Tiêu dùng thông
     minh và 3 câu ôn Bài 6 Quản lí thời gian hiệu quả (tình huống, câu hỏi khác với 10 câu Bài 6 của kho cuối kì I). Phạm vi theo đề cương giữa
     kì II GDCD 9 tra được ngày 28/10/2026 (Bài 6, 7, 8). Câu tự soạn: tình huống, nhân vật không lấy từ sách (nhân vật của sách mang
     tên một chữ cái), không dùng lại các trường hợp, nhận định của phần Khám phá, Luyện tập. Hai đề là kho của đề ngẫu nhiên
     "gdcd9-gk2-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận ở data/banks/index.js). Mỗi đề 25 câu chia đúng
     ma trận 10 Biết, 8 Hiểu, 7 Vận dụng: Bài 6 3 câu, Bài 7 11 câu, Bài 8 11 câu. Các ô của Bài 7, 8 rút từ 3 câu trở lên nên một lần
     rút có thể gặp câu của cả hai đề: mỗi câu trong ô hỏi một ý riêng, lời giải chỉ giải thích câu của nó, không nêu ý là đáp án câu
     khác. Cách xếp mức như kho cuối kì I. tests/lsdl-gdcd9-gk2.js tính lại câu chia việc của Bài 6, ba câu tính tiền của Bài 8 và
     kiểm tra thứ tự của câu sắp xếp. */
  "gdcd9-gk2-de1": {
    note: "Giáo dục công dân 9, sách Kết nối tri thức, giữa học kì II: Bài 7 Thích ứng với thay đổi; Bài 8 Tiêu dùng thông minh; 3 câu ôn Bài 6 Quản lí thời gian hiệu quả. Câu tình huống là chính. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Phạm vi của trường có thể khác, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu.",
    questions: [
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Ý nào sau đây nói đúng thế nào là quản lí thời gian hiệu quả?", o: ["Sắp xếp, dùng thời gian hợp lí, không để lãng phí, làm xong các việc theo kế hoạch đã định", "Dành phần lớn thời gian cho những việc mình thích, còn việc khó thì để dồn đến cuối mới làm", "Chỉ lập kế hoạch cho những việc lớn, còn việc hằng ngày thì làm tuỳ theo hứng thú", "Luôn làm xong việc nhanh hơn bạn bè, dù chất lượng công việc chưa được tốt"], x: "Quản lí thời gian hiệu quả là biết sắp xếp và sử dụng thời gian hợp lí, không để thời gian trôi qua vô ích, nhờ đó hoàn thành các việc theo kế hoạch. Để việc khó đến cuối, chỉ lên kế hoạch cho việc lớn hay làm nhanh mà ẩu đều chưa phải là quản lí thời gian hiệu quả.", lv: 1 },
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Bảo ghi vào sổ: “Nộp bài khảo sát Toán: thứ Ba; làm mô hình cho môn Khoa học tự nhiên: thứ Sáu; viết bài giới thiệu sách cho thư viện lớp: thứ Hai tuần sau.” Việc ghi rõ hạn của từng việc giúp Bảo điều gì?", o: ["Biết việc nào đến hạn trước để làm trước, không bị dồn việc vào phút cuối", "Không phải bắt tay vào làm việc nào trước khi đến hạn, vì mọi việc đã được ghi đủ vào sổ", "Được thầy cô cho thêm thời gian khi chưa làm xong việc đã ghi", "Có thể bỏ bớt việc khó mà không ảnh hưởng đến kết quả học tập"], x: "Ghi rõ thời hạn giúp Bảo biết việc nào cần xong sớm nhất (bài khảo sát Toán, hạn thứ Ba) để làm trước, rồi lần lượt đến các việc sau; nhờ vậy các việc không bị dồn lại sát hạn. Ghi thời hạn không giúp được thêm giờ hay bỏ bớt việc.", lv: 2 },
      { topic: "Quản lí thời gian hiệu quả", type: "order", q: "Còn hai tuần nữa là đến kì kiểm tra giữa học kì II, Linh muốn sắp xếp thời gian ôn tập thật hiệu quả. Hãy xếp các việc Linh nên làm theo thứ tự hợp lí.", o: ["Ghi ra các môn cần ôn và ngày kiểm tra của từng môn", "Xếp môn có ngày kiểm tra sớm hơn lên ôn trước", "Chia thời gian ôn từng môn vào các buổi tối trong hai tuần", "Mỗi buổi tối cất điện thoại, ôn đúng phần đã chia"], x: "Trước hết Linh xác định các việc cần làm và thời hạn (môn nào, ngày nào kiểm tra), tiếp theo đặt thứ tự ưu tiên theo ngày kiểm tra, rồi chia thời gian ôn cho từng môn, cuối cùng làm đúng kế hoạch, tránh những thứ làm mình sao nhãng.", lv: 3 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Trường hợp nào dưới đây là một thay đổi trong hoàn cảnh gia đình của học sinh?", o: ["Mẹ sinh em bé, cả nhà phải sắp xếp lại việc nhà và giờ giấc sinh hoạt", "Trường mở thêm câu lạc bộ bóng rổ, học sinh được tự chọn tham gia", "Thời tiết chuyển mùa, buổi sáng trời se lạnh hơn mấy hôm trước", "Một bạn trong lớp được cô giáo cho đổi chỗ lên bàn đầu để dễ nhìn bảng"], x: "Thay đổi trong hoàn cảnh gia đình là những đổi khác về các thành viên, nơi ở, công việc, thu nhập của gia đình. Có thêm em bé khiến nếp sinh hoạt của cả nhà thay đổi, các thành viên cần thích nghi. Câu lạc bộ mới, thời tiết, chỗ ngồi trong lớp không phải là thay đổi của hoàn cảnh gia đình.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Khi một thay đổi ngoài ý muốn đã xảy ra, thái độ nào dưới đây giúp em bắt đầu thích ứng?", o: ["Chấp nhận rằng điều đó đã xảy ra, thay vì đổ lỗi hay nổi giận", "Tìm xem ai là người có lỗi để trách móc cho nhẹ lòng", "Coi như không có chuyện gì, cứ sống như chưa từng thay đổi", "Giận dỗi mọi người trong nhà, bỏ bữa và không chịu đi học"], x: "Có những thay đổi không thể đảo ngược được. Chấp nhận rằng điều đó đã xảy ra, không trách người khác, không nổi giận hay quá lo âu, là bước đầu để ta bình tĩnh nhìn lại vấn đề và tìm cách đối diện. Trốn tránh, giận dỗi chỉ làm khó khăn kéo dài.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Để giữ bình tĩnh ngay khi gặp một biến cố bất ngờ, em có thể làm gì?", o: ["Hít thở thật sâu, chưa vội đưa ra quyết định", "Đưa ra ngay một quyết định để giải quyết cho xong", "Đăng ngay cảm xúc lên mạng xã hội cho mọi người biết", "Quát mắng người ở bên cạnh để giải toả bực bội"], x: "Hít thở thật sâu giúp cơ thể dịu lại, đầu óc tỉnh táo hơn; chưa vội quyết định để có thời gian xem xét vấn đề thấu đáo. Đăng cảm xúc lên mạng hay trút giận lên người khác lúc đang rối bời thường khiến mọi việc tệ hơn.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Biết thích ứng với những thay đổi trong cuộc sống giúp mỗi người:", o: ["Vượt qua khó khăn, sống phù hợp với hoàn cảnh mới và ngày càng trưởng thành", "Tránh được hết mọi thay đổi có thể xảy đến với bản thân và với cả gia đình mình", "Không bao giờ phải buồn phiền hay lo lắng về bất cứ chuyện gì", "Luôn được người khác đứng ra giải quyết giúp mọi khó khăn"], x: "Thích ứng tốt giúp ta vượt qua khó khăn khi hoàn cảnh đổi khác, sống hoà hợp với hoàn cảnh mới, qua đó học hỏi, rèn luyện và ngày càng hoàn thiện bản thân. Thích ứng không có nghĩa là không bao giờ buồn hay luôn có người khác lo giúp.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Bạn nào dưới đây đã biết thích ứng với thay đổi?", o: ["Từ khi bố mẹ đi làm ca đêm, Nhung tự đặt báo thức dậy đúng giờ, chuẩn bị bữa sáng cho mình và em", "Chuyển đến trường mới, Tú không chịu làm quen ai, giờ ra chơi chỉ ngồi một mình nhớ bạn cũ", "Nhà chuyển lên phố, Lực vẫn giữ thói quen ngủ dậy thật muộn như hồi ở quê nên tuần nào cũng đi học trễ", "Lớp chuyển sang học trực tuyến, Hằng tắt camera rồi chơi điện tử trong giờ học"], x: "Nhung chấp nhận thay đổi về giờ làm của bố mẹ và chủ động đổi nếp sinh hoạt của mình cho phù hợp: đó là biết thích ứng. Tú, Lực, Hằng chưa chịu thay đổi cách sống cho hợp với hoàn cảnh mới nên gặp khó khăn trong học tập, sinh hoạt.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Mỗi lần gặp chuyện không như ý, Phúc lại nói: “Thôi, kệ nó, rồi cũng qua” và không làm gì cả. Nhận xét nào về Phúc là đúng?", o: ["Phúc không hoảng hốt nhưng chưa chủ động tìm cách giải quyết, nên khó khăn vẫn còn nguyên", "Phúc đã thích ứng rất tốt vì không bao giờ tỏ ra lo lắng trước khó khăn", "Phúc làm đúng vì khó khăn nào rồi cũng tự hết mà không cần ai làm gì", "Phúc chưa đúng vì gặp chuyện không như ý thì phải nổi giận thật to mới mong giải quyết được"], x: "Chấp nhận, bình tĩnh là cần nhưng chưa đủ; còn phải chủ động suy nghĩ, tìm cách giải quyết tích cực, hợp với khả năng và điều kiện của mình. Phúc mặc kệ mọi việc nên khó khăn không tự mất đi.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Phần mềm học tập của trường chuyển sang phiên bản mới, nhiều chức năng khác trước. Thái bực bội, không chịu dùng; Diệu xem video giới thiệu, hỏi thầy cô và tập dùng dần. Nhận xét nào đúng?", o: ["Diệu chủ động tìm hiểu để thích nghi, còn Thái cứ bực bội nên sẽ gặp khó khăn hơn", "Thái làm đúng, vì đã quen phần mềm cũ thì không nên dùng phần mềm khác", "Cả hai bạn đều đúng, vì dùng hay không dùng phần mềm mới là việc riêng của mỗi người", "Diệu chưa đúng, vì hỏi thầy cô làm mất thời gian của thầy cô"], x: "Thay đổi về công cụ học tập là điều thường gặp. Diệu chấp nhận thay đổi, chủ động tìm hiểu, nhờ người hướng dẫn nên sẽ sớm dùng thành thạo phần mềm mới. Thái bực bội, không chịu học cách dùng nên sẽ bị chậm hơn trong học tập.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "tf4", q: "Mẹ của Hưng chuyển sang làm ở một công ti mới, không đưa Hưng đi học được nữa, Hưng phải tự đi xe buýt. Mỗi ý sau về cách thích ứng của Hưng đúng hay sai?", o: ["Hưng tìm hiểu tuyến xe, giờ xe chạy và đi thử cùng mẹ vào cuối tuần.", "Hưng nghỉ học những hôm mẹ không đưa đi được.", "Hưng bàn với mẹ cách liên lạc khi xe đến muộn hay có việc đột xuất.", "Hưng chờ mẹ đổi lại công việc cũ rồi mới tính chuyện tự đi học."], a: [true, false, true, false], x: "a), c) Đúng: tìm hiểu trước tuyến xe, đi thử, bàn cách liên lạc khi có việc bất ngờ là chủ động tìm cách giải quyết, phù hợp với hoàn cảnh mới. b), d) Sai: nghỉ học hay chờ hoàn cảnh trở lại như cũ là né tránh, không chấp nhận thay đổi.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Bố của Quân bị mất việc vì công ti thu hẹp sản xuất; cả nhà phải bớt chi tiêu, Quân không được học thêm ở câu lạc bộ bóng rổ như trước. Theo em, Quân nên làm gì?", o: ["Thông cảm với bố mẹ, cùng cả nhà bớt chi tiêu, rủ bạn tự tập bóng rổ ở sân trường", "Giận bố mẹ vì không cho đi học bóng rổ, bỏ luôn môn thể thao mình yêu thích", "Đòi bố mẹ vay tiền để Quân vẫn được học bóng rổ như trước, kẻo thua bạn bè", "Giấu nỗi buồn trong lòng, không nói với ai, bỏ bữa cho đến khi bố có việc làm mới"], x: "Khi kinh tế gia đình khó khăn, Quân nên chấp nhận thay đổi, động viên bố mẹ, cùng cả nhà tiết kiệm và tìm cách khác phù hợp để tiếp tục tập luyện (tập ở sân trường, tham gia hoạt động thể thao miễn phí của địa phương). Giận dỗi, đòi hỏi hay giấu buồn đều làm mọi người thêm khó khăn.", lv: 3 },
      { topic: "Thích ứng với thay đổi", type: "tf4", q: "Sắp đến ngày chuyển trường, Yến hồi hộp, lo mình sẽ không có bạn. Mỗi lời khuyên sau dành cho Yến đúng hay sai?", o: ["Tìm hiểu trước về trường mới qua trang thông tin của trường và hỏi bố mẹ.", "Cùng bố mẹ chuẩn bị trước đồ dùng, đường đi và giờ giấc đến trường mới.", "Xin nghỉ học vài tuần đầu cho đến khi hết hồi hộp.", "Đến lớp mới chỉ chơi với bạn cũ qua mạng, không cần làm quen ai."], a: [true, true, false, false], x: "a), b) Đúng: tìm hiểu trước về trường mới và chuẩn bị đồ dùng, đường đi, giờ giấc giúp Yến bớt bỡ ngỡ trong những ngày đầu. c), d) Sai: nghỉ học hay không chịu làm quen bạn mới là né tránh thay đổi, khiến Yến càng khó hoà nhập.", lv: 3 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Sau buổi khám mắt, bác sĩ cho biết Lam bị cận thị khá nặng, cần đeo kính thường xuyên và bớt thời gian dùng điện thoại. Lam sợ các bạn trêu nên giấu kính trong cặp. Theo em, Lam nên làm gì?", o: ["Đeo kính theo lời bác sĩ, bớt dùng điện thoại; bị trêu thì bình tĩnh nói rõ với bạn", "Không đeo kính ở lớp mà xin ngồi sát bảng, cố nheo mắt cho đến khi nhìn rõ được chữ", "Nghỉ học cho đến khi mắt tự khỏi, khi đó sẽ không cần đeo kính nữa", "Mua kính áp tròng trên mạng về tự đeo cho đẹp, không cần bác sĩ khám lại"], x: "Cận thị là thay đổi về sức khoẻ Lam cần chấp nhận và thích ứng: đeo kính đúng chỉ định để bảo vệ mắt, sắp xếp lại thời gian dùng điện thoại. Nếu bị trêu, Lam có thể bình tĩnh giải thích với bạn hoặc nhờ thầy cô giúp đỡ. Nheo mắt, bỏ kính hay tự mua kính trên mạng đều có hại cho mắt.", lv: 3 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Tiêu dùng thông minh mang lại lợi ích nào cho người tiêu dùng?", o: ["Mua được hàng tốt, hợp nhu cầu, đỡ tốn tiền bạc, thời gian, bảo vệ được sức khoẻ", "Được người bán tặng quà trong mỗi lần mua hàng, dù mua ít hay mua nhiều, ở bất kì đâu", "Không bao giờ phải chi bất cứ khoản tiền nào cho việc mua sắm", "Luôn mua được hàng với giá rẻ nhất, ở bất cứ cửa hàng nào"], x: "Tiêu dùng thông minh giúp ta mua được sản phẩm có chất lượng, đúng mục đích sử dụng, tiết kiệm tiền bạc và thời gian, giữ được kế hoạch chi tiêu, đồng thời giữ gìn sức khoẻ, quyền lợi của chính mình. Không ai luôn mua được giá rẻ nhất hay được tặng quà mọi lúc.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Trước khi mua một gói bánh cho em nhỏ, em cần kiểm tra những thông tin nào trên bao bì để bảo đảm an toàn?", o: ["Hạn sử dụng, thành phần, nơi sản xuất của sản phẩm", "Màu sắc, hình vẽ trên bao bì có đẹp, bắt mắt hay không", "Tên người bán hàng và giờ mở cửa của cửa hàng", "Số lượt thích bài quảng cáo gói bánh trên mạng"], x: "Trên bao bì cần đọc kĩ hạn sử dụng, thành phần (có chất em nhỏ bị dị ứng không), tên và địa chỉ nơi sản xuất; bao bì phải còn nguyên vẹn. Hình vẽ đẹp hay nhiều lượt thích không cho biết sản phẩm có an toàn hay không.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Khi thanh toán trực tuyến cho một đơn hàng, việc làm nào sau đây giúp bảo vệ tài khoản của em?", o: ["Giữ kín mật khẩu, mã OTP; chỉ thanh toán trên trang bán hàng uy tín", "Gửi mã OTP cho người bán qua tin nhắn để đơn hàng được giao nhanh hơn", "Lưu mật khẩu tài khoản vào điện thoại của bạn để khi cần thì nhờ trả hộ", "Bấm vào mọi đường link khuyến mãi gửi đến để nhận thêm mã giảm giá"], x: "Khi mua hàng trực tuyến cần bảo mật thông tin, tài khoản: không cho ai biết mật khẩu, mã OTP; chỉ trả tiền trước cho trang bán hàng, thương hiệu uy tín; không bấm vào đường link lạ. Kẻ gian hay giả làm người bán, người giao hàng để xin mã OTP.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Khi mua hàng, việc làm nào dưới đây giúp người tiêu dùng có căn cứ để đổi, trả hay khiếu nại nếu hàng bị lỗi?", o: ["Giữ lại hoá đơn, chứng từ giao dịch", "Bóc bỏ tem bảo hành ngay sau khi mua về", "Vứt hộp đựng và giấy hướng dẫn đi cho gọn", "Trả tiền mặt và không lấy hoá đơn cho nhanh"], x: "Hoá đơn, chứng từ giao dịch ghi rõ hàng đã mua, giá tiền, ngày mua, nơi bán; khi hàng bị lỗi, người mua dựa vào đó để đổi, trả, bảo hành hay khiếu nại. Tem bảo hành, hộp đựng cũng nên giữ lại trong thời gian bảo hành.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Khi lập kế hoạch chi tiêu với số tiền có hạn, em nên ưu tiên mua những thứ nào?", o: ["Những thứ thật sự cần cho học tập, sinh hoạt hằng ngày", "Những món đang được nhiều bạn trong lớp mua để không bị lạc hậu", "Những thứ đẹp mắt nhất trong cửa hàng, dù chưa biết dùng vào việc gì", "Những món có quà tặng kèm hấp dẫn, dù nhà đã có loại tương tự"], x: "Chi tiêu có kế hoạch là ưu tiên những thứ thiết yếu cho học tập, ăn uống, đi lại, vệ sinh cá nhân… phù hợp với số tiền mình có. Mua theo bạn bè, theo vẻ đẹp hay vì quà tặng kèm khi chưa cần là chi tiêu lãng phí.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Bạn nào dưới đây đã tiêu dùng thông minh?", o: ["Hoàng ghi lại mỗi khoản tiêu vặt trong tháng, bớt quà vặt để dành tiền mua chiếc ba lô đã định", "Thấy cửa hàng giảm giá một nửa, Lan mua liền ba chiếc áo dù tủ quần áo còn rất nhiều", "Dương mua bộ sạc điện thoại loại rẻ nhất ở chợ, mới dùng vài hôm đã nóng ran, không dám cắm nữa", "Mai tiêu hết tiền mừng tuổi chỉ trong một tuần vào đồ ăn vặt và đồ chơi theo trào lưu"], x: "Hoàng chi tiêu có kế hoạch: theo dõi các khoản chi, bớt khoản chưa cần để dành mua thứ đã định. Lan mua vì giảm giá dù chưa cần; Dương chỉ ham rẻ nên mua phải sạc kém chất lượng, không an toàn; Mai tiêu tiền theo ý thích nhất thời.", lv: 2 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Một trang bán hàng liên tục chạy dòng chữ: “Chỉ còn 10 phút! Giảm sốc 70%, mua ngay kẻo hết!” Vì sao người tiêu dùng cần bình tĩnh trước những lời mời như vậy?", o: ["Vì lời mời kiểu đó thúc ta quyết định vội, dễ mua thứ chưa cần hoặc hàng kém chất lượng", "Vì tất cả sản phẩm được giảm giá trên mạng đều là hàng giả, hàng nhái, không thể dùng được", "Vì hàng được giảm giá bao giờ cũng giao chậm hơn hàng bán đúng giá ban đầu", "Vì mua hàng trên mạng lúc nào cũng đắt hơn mua trực tiếp ở cửa hàng gần nhà"], x: "Những lời mời hối thúc (“chỉ còn vài phút”, “giảm sốc”) đánh vào tâm lí sợ bỏ lỡ, khiến người mua quyết định vội mà không kịp cân nhắc nhu cầu, chất lượng và giá cả. Cần tự hỏi mình có thật sự cần không rồi mới quyết định; không phải hàng giảm giá nào cũng là hàng kém.", lv: 2 },
      { topic: "Tiêu dùng thông minh", type: "tf4", q: "Trong giờ thảo luận về cách mua sắm, các bạn lớp 9A nêu ý kiến. Mỗi ý kiến sau đúng hay sai?", o: ["Hàng có giá cao nhất bao giờ cũng là lựa chọn tốt nhất.", "Có thể chọn hàng sản xuất trong nước nếu hàng đó tốt và hợp nhu cầu.", "Tiền mua hàng trực tuyến thì không cần tính vào kế hoạch chi tiêu.", "Học sinh cũng cần rèn thói quen mua sắm có kế hoạch, không chỉ người lớn."], a: [false, true, false, true], x: "b), d) Đúng: hàng trong nước tốt, giá hợp lí, đúng nhu cầu là lựa chọn tốt; ai cũng cần rèn thói quen mua sắm có kế hoạch để bảo đảm an toàn tài chính cho bản thân, gia đình. a), c) Sai: giá cao chưa chắc đã hợp với nhu cầu và khả năng chi trả; mọi khoản chi, kể cả mua trực tuyến, đều cần nằm trong kế hoạch chi tiêu.", lv: 2 },
      { topic: "Tiêu dùng thông minh", type: "num", q: "Cửa hàng bán hai loại nước rửa tay cùng chất lượng: chai 250 ml giá 30 000 đồng, chai 400 ml giá 44 000 đồng. Tính theo mỗi 100 ml, chai 400 ml rẻ hơn chai 250 ml bao nhiêu đồng?", ans: 1000, unit: "đồng", x: "Giá 100 ml của chai 250 ml: 30 000 : 250 × 100 = 12 000 (đồng). Giá 100 ml của chai 400 ml: 44 000 : 400 × 100 = 11 000 (đồng). Mỗi 100 ml, chai 400 ml rẻ hơn 12 000 − 11 000 = 1 000 (đồng). Chai lớn chỉ thật sự lợi khi cả nhà dùng hết.", lv: 3 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Lớp 9B có 600 000 đồng để mua dụng cụ, cây giống cho buổi trồng cây ở trường. Cách làm nào dưới đây hợp lí nhất?", o: ["Liệt kê thứ cần mua, ước tính tiền từng thứ cho tổng không quá 600 000 đồng rồi mới mua", "Ra cửa hàng thấy thứ gì cần thì mua ngay, hết tiền thì thôi, còn thiếu thứ gì thì bổ sung sau", "Mua thật nhiều cây giống loại đắt nhất cho đẹp, còn dụng cụ thì mượn tạm của các bạn", "Giao hết tiền cho một bạn tự quyết định mua gì, không cần bàn bạc với cả lớp"], x: "Cần lập kế hoạch chi tiêu trước khi mua: liệt kê dụng cụ, cây giống cần dùng, ước tính giá từng thứ sao cho tổng tiền không vượt quá 600 000 đồng, cả lớp cùng bàn bạc. Mua tuỳ hứng, mua đồ đắt cho đẹp hay giao hết cho một người dễ thiếu hụt, lãng phí.", lv: 3 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Bà nội của Tuấn nhận được cuộc gọi báo bà trúng thưởng một chiếc ti vi, chỉ cần chuyển trước 500 000 đồng tiền phí vận chuyển vào một tài khoản lạ. Tuấn nên khuyên bà thế nào?", o: ["Không chuyển tiền, nhờ bố mẹ kiểm tra lại qua số điện thoại chính thức của cửa hàng", "Chuyển tiền ngay kẻo bị người khác nhận mất phần thưởng", "Đọc cho người gọi số tài khoản ngân hàng và số căn cước của bà để họ tự chuyển tiền thưởng vào", "Vay tiền hàng xóm để chuyển phí, vì được ti vi thì vẫn có lợi hơn"], x: "Đó là dấu hiệu của lừa đảo: không ai phải trả tiền trước để nhận một giải thưởng mình không hề tham gia. Tuấn nên khuyên bà không chuyển tiền, nhờ bố mẹ kiểm tra lại qua số điện thoại chính thức của cửa hàng hoặc báo cho công an nếu cần. Giúp người thân mua sắm, chi tiêu an toàn cũng là việc người tiêu dùng thông minh nên làm.", lv: 3 }
    ]
  },
  "gdcd9-gk2-de2": {
    note: "Giáo dục công dân 9, sách Kết nối tri thức, giữa học kì II: Bài 7 Thích ứng với thay đổi; Bài 8 Tiêu dùng thông minh; 3 câu ôn Bài 6 Quản lí thời gian hiệu quả. Câu tình huống là chính. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Phạm vi của trường có thể khác, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu.",
    questions: [
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Thành ngữ “Nước đến chân mới nhảy” chê thói quen nào khi làm việc?", o: ["Để việc đến sát hạn mới bắt tay vào làm", "Làm việc quá nhanh nên hay mắc lỗi", "Nhận làm quá nhiều việc cùng một lúc", "Chỉ làm những việc mà mình yêu thích"], x: "“Nước đến chân mới nhảy” chê người hay trì hoãn, để việc dồn đến sát hạn mới vội làm, nên dễ làm ẩu, thiếu thời gian hoặc trễ hạn. Muốn tránh điều đó cần lập kế hoạch và giữ kỉ luật làm theo kế hoạch.", lv: 1 },
      { topic: "Quản lí thời gian hiệu quả", type: "mc", q: "Trong lúc chờ nồi cơm chín, Tường tranh thủ đọc lại các từ mới tiếng Anh ghi trong sổ tay. Việc làm của Tường thể hiện điều gì?", o: ["Biết sắp xếp công việc linh hoạt, tận dụng khoảng thời gian chờ đợi", "Đang lơ là việc nhà vì quá mải mê học thuộc các từ mới tiếng Anh trong sổ", "Làm hai việc cùng một lúc nên việc nào cũng sẽ bị dở dang", "Chưa có kế hoạch học tập nên phải học cả lúc đang nấu cơm"], x: "Cơm vẫn tự chín, Tường không bỏ việc nhà mà tranh thủ khoảng thời gian chờ để ôn từ mới: đó là sắp xếp công việc linh hoạt, tiết kiệm thời gian. Việc chờ cơm chín không đòi hỏi Tường phải chú ý liên tục nên không ảnh hưởng đến việc nào.", lv: 2 },
      { topic: "Quản lí thời gian hiệu quả", type: "num", q: "Còn 12 ngày nữa đến hạn nộp, nhóm của An phải hoàn thành 30 trang tập san của lớp. Nhóm dành 2 ngày cuối để đọc lại, sửa lỗi; những ngày còn lại, ngày nào cũng làm số trang như nhau. Mỗi ngày nhóm cần làm bao nhiêu trang?", ans: 3, unit: "trang", x: "Số ngày dùng để làm tập san: 12 − 2 = 10 (ngày). Mỗi ngày cần làm: 30 : 10 = 3 (trang).", lv: 3 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Nếu việc giải quyết một thay đổi lớn vượt quá khả năng của mình, em nên làm gì?", o: ["Chủ động nhờ người thân, thầy cô hay người lớn tin cậy giúp", "Tự cố gắng chịu đựng một mình, không để cho ai biết", "Làm theo lời khuyên của bất kì ai trên mạng xã hội", "Bỏ mặc mọi việc vì mình không thể thay đổi được gì"], x: "Việc quá sức mình thì nên nhờ bố mẹ, thầy cô, bạn bè hay người lớn mình tin tưởng cùng tìm cách. Lời khuyên của người lạ trên mạng có thể không đúng, thậm chí gây hại; chịu đựng một mình hay bỏ mặc chỉ làm khó khăn thêm nặng nề.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Thay đổi nào dưới đây đến từ chính bản thân em?", o: ["Vào tuổi dậy thì, cơ thể và tâm lí của em đổi khác nhiều", "Khu phố nơi em ở mở thêm một tuyến xe buýt mới chạy qua", "Trường của em đổi giờ vào học sớm hơn trước 15 phút", "Thành phố nơi em sống xây thêm một công viên lớn ở gần nhà"], x: "Thay đổi có khi do hoàn cảnh xung quanh (nơi ở, trường học, xã hội), có khi do chính mỗi người. Tuổi dậy thì làm cơ thể, cảm xúc, suy nghĩ của em thay đổi; em cần hiểu và thích ứng với những thay đổi đó. Tuyến xe buýt, giờ học, công viên mới là thay đổi từ bên ngoài.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Câu thành ngữ nào dưới đây khuyên con người biết thích nghi với nơi ở, hoàn cảnh mới?", o: ["Nhập gia tuỳ tục", "Ăn quả nhớ kẻ trồng cây", "Uống nước nhớ nguồn", "Có công mài sắt, có ngày nên kim"], x: "“Nhập gia tuỳ tục” nghĩa là đến sống ở nơi nào thì tìm hiểu và làm theo phong tục, nếp sống ở nơi đó, tức là biết thích nghi với hoàn cảnh mới. “Ăn quả nhớ kẻ trồng cây”, “Uống nước nhớ nguồn” nói về lòng biết ơn; “Có công mài sắt, có ngày nên kim” khuyên kiên trì.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Nhận định nào dưới đây đúng về những thay đổi trong cuộc sống?", o: ["Thay đổi có thể đến với bất kì ai, vào bất cứ lúc nào", "Chỉ người lớn mới gặp thay đổi, học sinh thì không", "Thay đổi chỉ xảy ra khi chính mình mong muốn điều đó", "Nếu đủ cẩn thận, ta có thể tránh được mọi thay đổi"], x: "Cuộc sống luôn vận động, nên thay đổi có thể đến với bất kì ai, vào bất cứ lúc nào, có khi đến từ hoàn cảnh bên ngoài, có khi từ chính bản thân. Vì vậy, ai cũng cần rèn kĩ năng thích ứng, kể cả học sinh.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Bạn thân nhất của Kiên theo gia đình ra nước ngoài sinh sống. Từ đó, Kiên buồn bã, không chơi với ai, giờ ra chơi chỉ ngồi một mình. Nếu cứ như vậy, điều gì có thể xảy ra với Kiên?", o: ["Kiên càng thu mình, thêm buồn và khó có thêm những người bạn mới", "Kiên sẽ sớm quên hẳn bạn cũ và tự nhiên có thêm thật nhiều bạn mới", "Các bạn trong lớp sẽ tự tìm đến chơi với Kiên mỗi ngày", "Bạn thân của Kiên sẽ phải quay về nước để chơi với Kiên"], x: "Thu mình, né tránh mọi người khiến nỗi buồn kéo dài, Kiên dễ bị cô lập và khó kết thêm bạn mới. Kiên nên chấp nhận sự xa cách, vẫn giữ liên lạc với bạn cũ qua thư, điện thoại, đồng thời mở lòng với các bạn trong lớp.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Ngọc được chọn vào đội tuyển học sinh giỏi của tỉnh, phải lên ôn luyện tập trung ba tuần xa nhà. Vì sao dù là tin vui, Ngọc vẫn cần chuẩn bị để thích ứng?", o: ["Vì nơi ở, nếp sinh hoạt, bạn học đều mới, Ngọc phải tự lo nhiều việc", "Vì tin vui thì không bao giờ đi kèm với bất kì khó khăn nào", "Vì Ngọc sẽ phải bỏ hẳn việc học ở trường mình trong cả năm học", "Vì ở đội tuyển, Ngọc hoàn toàn không được liên lạc với gia đình"], x: "Thay đổi tích cực cũng là thay đổi: ở nơi mới, Ngọc phải tự sắp xếp việc ăn ngủ, học tập, làm quen thầy cô, bạn học mới, xa sự chăm sóc của gia đình. Chuẩn bị trước (đồ dùng, cách liên lạc với gia đình, kế hoạch học) giúp Ngọc thích nghi nhanh và học tốt.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Từ năm học này, trường của Khải không cho học sinh dùng điện thoại trong giờ học. Khải thấy bất tiện vì đã quen tra cứu bằng điện thoại. Suy nghĩ nào dưới đây giúp Khải thích ứng với quy định mới?", o: ["“Quy định đã có thì mình làm theo, mình sẽ tập ghi chép và hỏi thầy cô khi cần”", "“Quy định này vô lí, mình sẽ lén dùng điện thoại trong giờ học”", "“Không có điện thoại thì mình không học được, nên nghỉ học cho xong”", "“Mình sẽ đợi đến khi nhà trường bỏ quy định này rồi mới chịu học hành nghiêm túc”"], x: "Quy định mới là thay đổi từ bên ngoài mà Khải không tự quyết được. Chấp nhận và tìm cách học khác (ghi chép, hỏi thầy cô, dùng sách ở thư viện) giúp Khải vẫn học tốt. Lén vi phạm, bỏ học hay chờ quy định thay đổi đều là không chịu thích ứng.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "tf4", q: "Khu nhà của Châu được giải toả để làm đường, cả nhà chuyển sang ở một căn nhà thuê nhỏ hơn. Mỗi ý sau về cách thích ứng của Châu đúng hay sai?", o: ["Châu trách bố mẹ, ngày nào cũng đòi chuyển về chỗ cũ.", "Châu cùng mẹ sắp xếp lại một góc học tập gọn gàng trong nhà mới.", "Châu làm quen với các bạn hàng xóm mới, rủ nhau cùng đi học.", "Châu xin nghỉ học vài hôm cho đến khi quen chỗ ở mới."], a: [false, true, true, false], x: "b), c) Đúng: sắp xếp lại góc học tập, làm quen với hàng xóm mới là chủ động tìm cách giải quyết, phù hợp với hoàn cảnh mới. a), d) Sai: trách bố mẹ, đòi về chỗ cũ hay nghỉ học là không chấp nhận thay đổi, làm việc học và sinh hoạt thêm khó khăn.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Đội văn nghệ của lớp do Hạnh làm nhóm trưởng đã tập một tiết mục hai tuần, nhưng trước ngày diễn hai hôm, bạn hát chính bị ốm. Hạnh nên làm gì?", o: ["Bình tĩnh bàn với cả nhóm chia lại phần hát, tập thêm, báo cô giáo để được giúp", "Huỷ luôn tiết mục, vì thiếu bạn hát chính thì cả nhóm chắc chắn không thể diễn được nữa", "Trách bạn hát chính không biết giữ sức khoẻ làm cả nhóm thất bại", "Giữ nguyên tiết mục, đến hôm diễn bạn nào hát được thì hát"], x: "Gặp thay đổi bất ngờ, Hạnh cần giữ bình tĩnh, cùng cả nhóm tìm cách giải quyết phù hợp (chia lại phần hát, tập thêm) và nhờ thầy cô hỗ trợ. Huỷ tiết mục, trách bạn hay để mặc đến hôm diễn đều không giúp được nhóm.", lv: 3 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Toàn không đỗ vào trường chuyên như mong muốn mà học ở một trường gần nhà. Lời khuyên nào dưới đây phù hợp nhất với Toàn?", o: ["Chấp nhận kết quả, đặt mục tiêu học tốt ở trường mới, tham gia câu lạc bộ mình thích", "Tự trách mình mãi, không muốn gặp lại bất kì bạn cũ nào đã đỗ vào trường chuyên năm nay", "Học thật qua loa ở trường mới vì đây không phải nơi mình muốn học", "Đổ lỗi cho đề thi quá khó và bỏ không tham gia hoạt động nào nữa"], x: "Không đạt được điều mong muốn cũng là một thay đổi lớn. Toàn nên chấp nhận kết quả, bình tâm nhìn lại, đặt mục tiêu mới phù hợp và tiếp tục phát triển thế mạnh ở trường mới. Tự trách, học qua loa hay đổ lỗi chỉ làm Toàn chậm tiến bộ.", lv: 3 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Lớp của Vân chuyển sang học trực tuyến hai tuần vì trường sửa chữa phòng học. Vân nên làm gì để thích ứng?", o: ["Chọn góc học yên tĩnh, kiểm tra trước máy và mạng, giữ giờ học như ở trường", "Ngủ dậy lúc nào thì học lúc ấy, vì học ở nhà thì không có ai nhắc nhở", "Vừa học vừa xem phim cho đỡ chán vì thầy cô không nhìn thấy", "Nghỉ hẳn hai tuần học trực tuyến rồi nhờ bạn chép lại bài giúp khi đi học trở lại"], x: "Học trực tuyến là thay đổi về cách học. Vân cần chuẩn bị chỗ học yên tĩnh, kiểm tra trước thiết bị, đường truyền, giữ nếp giờ giấc như khi học ở trường và tập trung trong giờ học. Học tuỳ hứng, vừa học vừa xem phim hay bỏ học đều làm Vân bị hổng kiến thức.", lv: 3 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Hình thức nào dưới đây là quảng cáo sản phẩm?", o: ["Video người nổi tiếng giới thiệu một loại sữa do hãng sữa trả tiền", "Hai bạn kể cho nhau nghe món ăn ngon mà mẹ đã nấu ở nhà vào tối hôm qua", "Cô giáo dặn cả lớp nhớ mang theo áo mưa trong mùa mưa", "Bản tin thời tiết báo ngày mai nhiều nơi có mưa rào"], x: "Quảng cáo là những thông tin giới thiệu sản phẩm nhằm thuyết phục người mua, như biển hiệu, tờ rơi, video, bài đăng trên mạng; nhiều quảng cáo nhờ người nổi tiếng giới thiệu và được nhà sản xuất trả tiền. Người tiêu dùng không nên tin hoàn toàn vào quảng cáo.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Khi nhận một đơn hàng mua trên mạng, việc nào em nên làm trước khi trả tiền cho người giao hàng?", o: ["Kiểm tra hàng có đúng loại, đủ số lượng, còn nguyên vẹn", "Trả tiền ngay cho người giao hàng để họ khỏi phải đứng chờ lâu ở cửa", "Nhận hàng giúp hàng xóm rồi để họ tự trả tiền sau", "Xoá ngay tin nhắn xác nhận đơn hàng cho gọn máy"], x: "Khi nhận hàng mua trực tuyến, cần kiểm tra kĩ: đúng sản phẩm đã đặt, đủ số lượng, không hư hỏng, rồi mới trả tiền. Hàng sai hoặc hỏng thì có thể từ chối nhận ngay tại chỗ.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Nhà Minh mới mua một chiếc nồi chiên không dầu. Trước khi dùng lần đầu, việc quan trọng nhất cần làm là gì?", o: ["Đọc kĩ hướng dẫn sử dụng và làm theo đúng cách", "Bật nồi ở nhiệt độ cao nhất xem nồi có mạnh không", "Bỏ hết giấy tờ kèm theo vì nồi dùng rất đơn giản", "Cho thật nhiều thức ăn vào để thử sức chứa của nồi"], x: "Đồ dùng điện cần dùng đúng cách để an toàn: đọc kĩ hướng dẫn sử dụng (cách lắp đặt, lượng thức ăn, nhiệt độ, cách vệ sinh) và làm theo. Dùng sai cách có thể làm hỏng sản phẩm, thậm chí gây cháy, bỏng.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Khi mua hàng, người tiêu dùng nên chọn phương thức thanh toán như thế nào?", o: ["Trả tiền mặt hay trả trực tuyến tuỳ hoàn cảnh, điều kiện của mình", "Luôn chuyển khoản trả trước cho mọi người bán hàng, kể cả người lạ trên mạng", "Chỉ trả tiền mặt, tuyệt đối không bao giờ trả trực tuyến", "Nhờ người bán giữ thẻ ngân hàng để tự trừ tiền mỗi lần mua"], x: "Có thể trả tiền mặt hay trả qua mạng (chuyển khoản, quét mã), tuỳ hoàn cảnh và điều kiện của mình; trước khi trả cần xem lại số tiền phải thanh toán. Không chuyển tiền trước cho người bán không rõ ràng.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Để có thông tin chính xác về một sản phẩm định mua, em nên làm gì?", o: ["Tìm hiểu từ nhiều nguồn khác nhau rồi so sánh, chọn lọc thông tin", "Chỉ cần tin vào lời giới thiệu của người bán hàng là đủ, không cần tìm hiểu thêm", "Chỉ xem một video quảng cáo hay nhất về sản phẩm đó thôi", "Chọn ngay sản phẩm có bao bì đẹp và có giá đắt nhất"], x: "Nên tìm hiểu thông tin sản phẩm (giá, chất lượng, công dụng, mẫu mã) qua nhiều kênh: thông tin trên bao bì, trang của nhà sản xuất, mã truy xuất nguồn gốc, nhận xét của người đã dùng…, rồi so sánh, chọn lọc. Lời người bán hay một video quảng cáo thường chỉ nói điểm tốt của sản phẩm.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Siêu thị có chương trình “mua 3 tặng 1” với một loại sữa chua. Nhà Hiền mỗi tuần chỉ dùng 2 hộp. Vì sao mẹ Hiền vẫn chỉ mua 2 hộp?", o: ["Mua quá nhu cầu, dùng không hết lại phải bỏ đi, gây lãng phí", "Vì hàng được khuyến mãi bao giờ cũng là hàng kém chất lượng", "Vì siêu thị không cho mỗi khách mua nhiều hơn hai hộp mỗi lần", "Vì mua đủ ba hộp thì cũng không được tặng thêm hộp nào cả"], x: "Khuyến mãi chỉ có lợi khi mình thật sự cần và dùng hết. Nhà Hiền mỗi tuần dùng 2 hộp, mua 4 hộp (3 tặng 1) thì dễ phải bỏ đi phần thừa, tốn thêm tiền mà không dùng được. Hàng khuyến mãi không phải bao giờ cũng là hàng kém.", lv: 2 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Mỗi lần buồn chuyện ở lớp, Thắng lại đặt mua vài món đồ trên mạng “cho vui”, nhiều món mua về không dùng đến. Nhận xét nào về Thắng là đúng?", o: ["Thắng mua theo cảm xúc nhất thời, không theo nhu cầu, dễ lãng phí", "Thắng mua sắm hợp lí, vì mua sắm luôn là cách tốt nhất để giải toả nỗi buồn", "Thắng làm đúng vì mua đồ trên mạng bao giờ cũng rẻ hơn mua ở cửa hàng", "Thắng không có lỗi vì tiền mua đồ là tiền của mình"], x: "Mua sắm để giải toả cảm xúc khiến ta mua những thứ không cần, tốn tiền mà không giải quyết được nỗi buồn. Khi buồn, Thắng nên chia sẻ với người thân, bạn bè hoặc làm việc mình thích như chơi thể thao, đọc sách; mua sắm cần dựa vào nhu cầu và kế hoạch chi tiêu.", lv: 2 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Đạt cần một chiếc máy tính cầm tay để học Toán nhưng tiền để dành chưa đủ mua máy mới. Đạt mua lại chiếc máy cũ còn tốt của anh họ với giá bằng một nửa máy mới. Nhận xét nào về Đạt là đúng?", o: ["Đạt chọn cách mua hợp với khả năng chi trả mà vẫn đáp ứng được nhu cầu", "Đạt chưa đúng vì đồ cũ thì không bao giờ nên mua", "Đạt chưa đúng vì phải chờ để dành đủ tiền mua loại máy đắt nhất", "Đạt chưa đúng vì nên mượn tiền của bạn bè để mua ngay một chiếc máy mới tinh"], x: "Đạt có nhu cầu thật (học Toán), chọn cách mua vừa với số tiền mình có mà máy vẫn dùng tốt: đó là mua sắm hợp lí. Đồ cũ còn tốt, giá phù hợp vẫn là lựa chọn đáng cân nhắc; vay mượn để mua đồ đắt khi chưa cần là chi tiêu quá sức.", lv: 2 },
      { topic: "Tiêu dùng thông minh", type: "num", q: "Mẹ nhờ Minh đi siêu thị mua 2 hộp sữa, mỗi hộp 32 000 đồng, và 3 gói bánh, mỗi gói 18 500 đồng. Khi thanh toán, máy tính tiền ghi tổng cộng 138 000 đồng. Minh tính lại thì thấy số tiền bị tính thừa bao nhiêu đồng?", ans: 18500, unit: "đồng", x: "Số tiền đúng: 2 × 32 000 + 3 × 18 500 = 64 000 + 55 500 = 119 500 (đồng). Số tiền bị tính thừa: 138 000 − 119 500 = 18 500 (đồng), bằng giá một gói bánh: có thể một gói bánh bị tính hai lần. Đây là lí do nên xem lại hoá đơn sau mỗi lần mua.", lv: 3 },
      { topic: "Tiêu dùng thông minh", type: "tf4", q: "Lâm muốn mua một chiếc mũ bảo hiểm để đi xe đạp điện đến trường. Mỗi việc làm sau của Lâm đúng hay sai?", o: ["Chọn mũ có tem hợp quy, đạt tiêu chuẩn chất lượng.", "Chọn loại rẻ nhất vì mũ nào đội lên cũng như nhau.", "Mua loại mũ nhựa mỏng, nhẹ như mũ đồ chơi cho mát đầu.", "Đội thử để chọn mũ vừa đầu, cài quai chắc chắn."], a: [true, false, false, true], x: "a), d) Đúng: mũ đạt chuẩn có tem hợp quy; mũ vừa đầu, cài quai chắc mới bảo vệ được đầu khi có va chạm. b), c) Sai: mũ rẻ nhất hay mũ nhựa mỏng thường không đạt chuẩn, không bảo vệ được người đội.", lv: 3 },
      { topic: "Tiêu dùng thông minh", type: "num", q: "Gia đình Phương đang trả cước internet 220 000 đồng mỗi tháng. Nhà mạng mời chuyển sang gói trả trước cả năm (12 tháng) giá 2 400 000 đồng, chất lượng như gói cũ. Nếu chuyển sang gói mới, mỗi năm gia đình tiết kiệm được bao nhiêu đồng?", ans: 240000, unit: "đồng", x: "Trả theo tháng, mỗi năm gia đình trả 220 000 × 12 = 2 640 000 (đồng). Gói trả trước cả năm giá 2 400 000 đồng, tiết kiệm được 2 640 000 − 2 400 000 = 240 000 (đồng). Gói này hợp lí khi gia đình chắc chắn dùng internet cả năm và đủ tiền trả một lần.", lv: 3 }
    ]
  },
  /* ---------- GDCD 9 · Kiểm tra cuối năm học (Kết nối tri thức; Phiên N9-ck2-lsdl-gdcd) ----------
     Sách Giáo dục công dân 9 in năm 2026 (OnUp-Book lop-9/giao-duc-cong-dan-9), Bài 7–10 theo mục lục: Thích ứng với thay đổi; Tiêu
     dùng thông minh; Vi phạm pháp luật và trách nhiệm pháp lí; Quyền tự do kinh doanh và nghĩa vụ nộp thuế; trọng tâm Bài 9–10. Câu
     về pháp luật theo chữ của sách in năm 2026: Hiến pháp năm 2013 (sửa đổi, bổ sung năm 2025), Bộ luật Hình sự năm 2015 (sửa đổi,
     bổ sung năm 2017, 2025), Luật Đầu tư năm 2025. Câu tự soạn: tình huống, nhân vật không lấy từ sách (nhân vật của sách mang tên
     một chữ cái), không dùng lại các trường hợp, nhận định của phần Khám phá, Luyện tập; câu Bài 7, 8 hỏi ý khác kho giữa kì II. Hai
     đề là kho của đề ngẫu nhiên "gdcd9-ck2-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận ở
     data/banks/index.js). Mỗi đề 25 câu chia đúng ma trận 10 Biết, 8 Hiểu, 7 Vận dụng: Bài 7 3 câu, Bài 8 4 câu, Bài 9 9 câu, Bài 10
     9 câu; phần lớn là câu tình huống. Các ô của Bài 9, 10 rút từ 2 câu trở lên nên một lần rút có thể gặp câu của cả hai đề: mỗi
     câu trong ô hỏi một ý riêng (dấu hiệu, loại vi phạm, loại trách nhiệm, biện pháp, ý nghĩa; quyền, nghĩa vụ, loại thuế), lời giải
     chỉ giải thích câu của nó, không nêu ý là đáp án câu khác. Cách xếp mức như kho cuối kì I. tests/lsdl-gdcd9-ck2.js tính lại câu
     tiền để dành của Bài 8 và câu thuế giá trị gia tăng của Bài 10. */
  "gdcd9-ck2-de1": {
    note: "Giáo dục công dân 9, sách Kết nối tri thức, cuối năm học: Bài 7 Thích ứng với thay đổi; Bài 8 Tiêu dùng thông minh; trọng tâm Bài 9 Vi phạm pháp luật và trách nhiệm pháp lí, Bài 10 Quyền tự do kinh doanh và nghĩa vụ nộp thuế. Câu về pháp luật theo sách in năm 2026 (Hiến pháp năm 2013 sửa đổi, bổ sung năm 2025; Bộ luật Hình sự năm 2015 sửa đổi, bổ sung năm 2017, 2025; Luật Đầu tư năm 2025). Câu tình huống là chính. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Phạm vi của trường có thể khác, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 9; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Bố của Hà được cử đi làm việc ở tỉnh khác một năm, Hà phải tự lo nhiều việc hơn ở nhà. Sau mấy ngày lo lắng, Hà đã chấp nhận sự việc và bình tĩnh lại. Hà nên làm gì tiếp theo để thích ứng?", o: ["Tìm hiểu, chọn cách giải quyết tích cực, hợp với hoàn cảnh", "Chờ cho mọi việc tự trở lại như cũ rồi mới tính đến việc khác", "Giữ kín chuyện trong lòng, không chia sẻ với bất kì ai", "Làm ngay theo ý kiến đầu tiên mà bạn bè gợi ý cho mình"], x: "Thích ứng với thay đổi gồm ba việc: chấp nhận thay đổi là điều khó tránh; giữ bình tĩnh để suy xét; rồi chủ động tìm hiểu, tham khảo, chọn cách giải quyết tích cực, phù hợp nhất (như lập thời gian biểu, chia việc nhà với mẹ). Nếu việc vượt quá sức mình, hãy nhờ người thân, thầy cô hoặc người lớn tin cậy giúp đỡ.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Lên lớp 9, lớp của Hải có cô giáo chủ nhiệm mới, cách quản lí lớp khác hẳn trước. Hải than: “Cô mới khó quá, mình chẳng muốn đi học nữa.” Nhận xét nào dưới đây về Hải là đúng?", o: ["Hải chưa chấp nhận thay đổi; nên tìm hiểu cách làm của cô và điều chỉnh dần", "Hải nói đúng, vì học sinh có quyền không thích thì không cần đi học", "Hải nên xin chuyển ngay sang một trường khác cho đỡ thấy khó chịu", "Hải đã thích ứng tốt vì dám nói thẳng ra suy nghĩ của mình với các bạn trong lớp"], x: "Đổi giáo viên chủ nhiệm là thay đổi thường gặp ở trường. Muốn bỏ học vì chưa quen là để cảm xúc chi phối. Hải cần bình tĩnh, tìm hiểu vì sao cô làm như vậy, mạnh dạn hỏi khi chưa hiểu, rồi điều chỉnh nếp học cho phù hợp.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Từ học kì II, trường của Khoa chuyển sang học hai buổi mỗi ngày, Khoa không còn giờ đá bóng buổi chiều như trước nên thấy bức bối. Cách nào dưới đây giúp Khoa thích ứng tốt nhất?", o: ["Lập lại thời gian biểu: tập thể dục sáng sớm, đá bóng với bạn vào cuối tuần", "Trốn bớt tiết học buổi chiều để ra sân đá bóng cùng các bạn như hồi học kì I", "Bỏ hẳn thể thao, dành toàn bộ thời gian rảnh để học thêm cho giỏi", "Thức thật khuya chơi trò chơi điện tử để bù lại thời gian đã mất"], x: "Lịch học thay đổi là việc Khoa không tự quyết được. Thay vì bực bội hay trốn học, Khoa chấp nhận, rồi sắp xếp lại giờ giấc để vẫn giữ thói quen vận động tốt cho sức khoẻ. Bỏ hẳn thể thao hay thức khuya chơi điện tử đều không có lợi.", lv: 3 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Ý nào dưới đây nói đúng về tiêu dùng thông minh?", o: ["Mua có kế hoạch, đúng nhu cầu, tiết kiệm và hợp với khả năng của mình", "Mua thật nhiều hàng mỗi khi có chương trình giảm giá, kể cả thứ chưa cần", "Luôn chọn mua món hàng đắt nhất vì nghĩ hàng đắt thì chắc chắn tốt nhất", "Mua những thứ đang được nhiều người khác mua để không thua kém bạn bè"], x: "Tiêu dùng thông minh là biết chi tiêu theo kế hoạch, mua đúng thứ mình cần, tiết kiệm tiền bạc, thời gian và phù hợp với bản thân. Chạy theo giảm giá, chọn hàng đắt hay mua theo đám đông dễ gây lãng phí.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Khi mua thực phẩm đóng gói, việc quét mã vạch, mã QR trên bao bì giúp người tiêu dùng điều gì?", o: ["Truy xuất nguồn gốc, kiểm tra thông tin về sản phẩm", "Được giảm giá ngay khi thanh toán ở quầy thu ngân của siêu thị", "Biết chắc sản phẩm ngon hơn mọi loại cùng giá", "Không cần đọc hạn sử dụng in trên bao bì nữa"], x: "Quét mã vạch, mã QR giúp xem nguồn gốc, nơi sản xuất và các thông tin khác của sản phẩm, là một cách tìm hiểu sản phẩm trước khi mua. Dù đã quét mã, người mua vẫn nên xem hạn dùng và thành phần ghi trên bao bì.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Bà của Tú hay mua thuốc bổ qua các buổi bán hàng trực tiếp trên mạng vì người bán hứa uống vào sẽ “khỏi hẳn mọi bệnh”. Vì sao Tú nên khuyên bà thận trọng?", o: ["Lời quảng cáo có thể phóng đại, hàng chưa rõ chất lượng có thể hại sức khoẻ", "Mọi việc mua hàng qua mạng đều bị pháp luật cấm", "Thuốc bổ chỉ dành cho người trẻ tuổi, còn người cao tuổi thì không nên dùng", "Người lớn tuổi không được tự quyết định tiêu tiền của chính mình"], x: "Không thuốc bổ nào chữa “khỏi hẳn mọi bệnh”; đó là lời quảng cáo phóng đại để kéo người mua. Tú nên giúp bà tìm hiểu thông tin sản phẩm ở nhiều nguồn tin cậy, hỏi ý kiến bác sĩ, chỉ mua sản phẩm có nguồn gốc rõ ràng.", lv: 2 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Nhà Quang định mua một chiếc tủ lạnh. Mỗi người trong nhà nêu một ý. Ý nào thể hiện cách tiêu dùng thông minh?", o: ["So sánh điện năng tiêu thụ, dung tích, bảo hành ở vài cửa hàng uy tín rồi chọn", "Chọn chiếc to nhất, đắt nhất trong cửa hàng cho sang, dù cả nhà chỉ có ba người", "Mua ngay chiếc đang giảm giá 50% của một người bán lạ trên mạng cho rẻ", "Chọn chiếc có màu đẹp nhất, hợp với bếp, không cần xem thêm thông tin gì"], x: "Nhà có ba người thì cần tủ vừa đủ dùng. Tiêu dùng thông minh: xác định nhu cầu, tìm hiểu thông tin sản phẩm (điện năng tiêu thụ, dung tích, bảo hành), so sánh ở nơi bán uy tín. Mua đồ to quá nhu cầu vừa tốn tiền vừa tốn điện; mua của người bán lạ dễ gặp hàng kém chất lượng.", lv: 3 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Một dấu hiệu của vi phạm pháp luật là hành vi có lỗi. Lỗi của người thực hiện hành vi trái pháp luật gồm những loại nào?", o: ["Lỗi cố ý và lỗi vô ý", "Lỗi nặng và lỗi nhẹ", "Lỗi cá nhân và lỗi tập thể", "Lỗi do mình và lỗi do người khác"], x: "Lỗi gồm lỗi cố ý (biết việc làm là sai, có hại mà vẫn làm) và lỗi vô ý (không thấy trước hậu quả dù cần phải thấy, hoặc thấy trước nhưng cho rằng sẽ không xảy ra).", lv: 1 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Biện pháp nào dưới đây thuộc trách nhiệm kỉ luật?", o: ["Hạ bậc lương", "Phạt tiền", "Buộc bồi thường thiệt hại", "Tịch thu tang vật vi phạm"], x: "Hạ bậc lương là một hình thức của trách nhiệm kỉ luật, cùng với khiển trách, cảnh cáo, buộc thôi việc.", lv: 1 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Anh Đức (30 tuổi) chở hàng cồng kềnh vượt quá kích thước cho phép trên xe máy và bị cảnh sát giao thông phạt tiền. Anh Đức phải chịu loại trách nhiệm pháp lí nào?", o: ["Trách nhiệm hành chính", "Trách nhiệm hình sự", "Trách nhiệm dân sự", "Trách nhiệm kỉ luật"], x: "Chở hàng quá kích thước cho phép là trái quy định về an toàn giao thông; anh Đức bị xử phạt hành chính bằng hình thức phạt tiền.", lv: 1 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Trách nhiệm pháp lí chỉ phát sinh trong trường hợp nào?", o: ["Khi có cá nhân, tổ chức thực hiện hành vi trái pháp luật", "Khi có người bị bạn bè, hàng xóm phê bình", "Khi có người làm việc không đúng sở thích của người khác", "Khi một người bị nghi ngờ nhưng chưa có hành vi nào"], x: "Trách nhiệm pháp lí do pháp luật quy định, chỉ phát sinh khi có hành vi vi phạm pháp luật; khi đó, cơ quan, người có thẩm quyền của Nhà nước buộc người vi phạm chịu những biện pháp cưỡng chế.", lv: 1 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "match", q: "Nối mỗi hành vi ở cột trái với loại vi phạm pháp luật tương ứng ở cột phải.", l: ["Anh Hưng (35 tuổi) dùng dao đe doạ, cướp tài sản của người đi đường", "Chị Lan làm vỡ điện thoại của bạn khi mượn nhưng không chịu đền", "Ông Quý đổ trộm phế thải xây dựng ra lòng đường", "Anh Toàn, công nhân, nhiều lần bỏ vị trí làm việc khi chưa hết ca, trái nội quy của nhà máy"], r: ["Vi phạm hình sự", "Vi phạm dân sự", "Vi phạm hành chính", "Vi phạm kỉ luật"], x: "Cướp tài sản là tội phạm (vi phạm hình sự). Không chịu đền tài sản đã làm hỏng của người khác là vi phạm dân sự. Đổ phế thải ra đường vi phạm quy định của Nhà nước về trật tự, vệ sinh nhưng chưa đến mức tội phạm (vi phạm hành chính). Bỏ vị trí làm việc trái nội quy là vi phạm kỉ luật.", lv: 2 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "tf4", q: "Mỗi nhận định sau đúng hay sai?", o: ["Bạn Tâm (14 tuổi) không chào khi gặp người lớn tuổi trong xóm là vi phạm pháp luật.", "Ông Thịnh (50 tuổi) tự ý chặt cây xanh trên vỉa hè để làm chỗ để xe là vi phạm pháp luật.", "Chị Na (28 tuổi) dùng tài khoản mạng xã hội giả để nhận tiền đặt hàng rồi không giao hàng là vi phạm pháp luật.", "Chú Hùng (35 tuổi) săn bắt chim quý hiếm trong rừng đặc dụng là vi phạm pháp luật."], a: [false, true, true, true], x: "a) Sai: không chào hỏi là thiếu lễ phép (trái chuẩn mực đạo đức), pháp luật không buộc phải làm. b) Đúng: cây xanh trên vỉa hè là tài sản công, tự ý chặt là trái pháp luật. c) Đúng: dùng tài khoản giả để chiếm đoạt tiền của người khác là lừa đảo. d) Đúng: săn bắt động vật quý hiếm trong rừng đặc dụng bị pháp luật nghiêm cấm.", lv: 2 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Bé Su (5 tuổi) chơi bóng làm vỡ kính cửa sổ nhà hàng xóm. Vì sao việc làm của bé Su không bị coi là vi phạm pháp luật?", o: ["Vì bé chưa đủ tuổi, chưa nhận thức được đầy đủ hành vi của mình", "Vì tấm kính cửa sổ nhà hàng xóm có giá trị quá nhỏ, không đáng kể", "Vì làm vỡ đồ khi chơi bóng thì không bao giờ gây ra thiệt hại gì", "Vì hàng xóm chưa đến công an để trình báo sự việc"], x: "Chỉ người có năng lực trách nhiệm pháp lí (đạt độ tuổi luật định, nhận thức và điều khiển được hành vi của mình) mới có thể vi phạm pháp luật. Bé Su mới 5 tuổi nên chưa có năng lực đó; bố mẹ bé nên xin lỗi và đền bù cho hàng xóm.", lv: 2 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Nhóm bạn của Tín rủ nhau dùng sơn xịt vẽ bậy lên tường nhà văn hoá thôn cho “ngầu”. Tín nên làm gì?", o: ["Từ chối, khuyên các bạn dừng lại; các bạn vẫn làm thì báo người lớn", "Tham gia vẽ cùng các bạn để không bị cả nhóm chê là nhát gan, kém vui", "Đứng xem các bạn vẽ rồi quay video lại, đăng lên mạng xã hội cho vui", "Lặng lẽ bỏ về nhà, coi như mình không hề biết gì về việc đó cả"], x: "Vẽ bậy lên công trình công cộng là làm hư hỏng tài sản chung, trái pháp luật, có thể bị xử phạt và phải khắc phục hậu quả. Tín cần giữ lập trường, không tham gia, khuyên ngăn bạn và báo người lớn để ngăn chặn kịp thời.", lv: 3 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Trên đường đi học về, Quân thấy hai người lạ đang dùng dụng cụ cạy khoá một chiếc xe máy dựng trước cổng nhà dân. Cách làm nào dưới đây phù hợp và an toàn nhất?", o: ["Giữ khoảng cách an toàn, báo ngay cho người lớn gần đó hoặc gọi số 113", "Một mình lao vào giằng lấy dụng cụ của hai người đó để ngăn lại", "Coi như không thấy vì đó không phải xe của nhà mình", "Đứng gần quay video lại, chờ đăng lên mạng xong rồi mới báo cho người khác"], x: "Ngăn ngừa, đấu tranh với hành vi vi phạm pháp luật cần đúng cách, không để mình gặp nguy hiểm. Quân nên tránh xa, nhanh chóng báo người lớn, chủ nhà hoặc gọi 113 (cảnh sát) để kịp thời ngăn chặn kẻ trộm.", lv: 3 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Theo Điều 33 Hiến pháp năm 2013 (sửa đổi, bổ sung năm 2025), công dân được tự do kinh doanh trong phạm vi nào?", o: ["Mọi ngành nghề, trừ những ngành nghề bị pháp luật cấm", "Chỉ những ngành nghề do Nhà nước giao riêng cho từng người", "Bất cứ ngành nghề nào mình thích, kể cả ngành bị cấm", "Chỉ những ngành nghề mà gia đình đã làm từ trước"], x: "Hiến pháp ghi nhận quyền tự do kinh doanh trong các ngành nghề pháp luật không cấm: mọi người được tự chọn ngành nghề, mô hình, quy mô kinh doanh hợp với khả năng của mình đồng thời phải chấp hành pháp luật về kinh doanh.", lv: 1 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Ngành nghề nào dưới đây bị cấm đầu tư kinh doanh ở Việt Nam?", o: ["Kinh doanh pháo nổ", "Mở tiệm sửa xe đạp", "Bán văn phòng phẩm", "Mở lớp dạy vẽ cho thiếu nhi"], x: "Theo Luật Đầu tư năm 2025, kinh doanh pháo nổ thuộc nhóm ngành nghề bị cấm đầu tư kinh doanh vì đe doạ tính mạng, tài sản của người dân. Sửa xe đạp, bán văn phòng phẩm, dạy vẽ là những việc kinh doanh bình thường.", lv: 1 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Người nộp thuế có nghĩa vụ nào dưới đây?", o: ["Đăng kí, kê khai trung thực và nộp đủ thuế đúng hạn", "Tự quyết định số tiền thuế mà mình muốn nộp trong mỗi năm", "Chỉ nộp thuế khi được cơ quan thuế nhắc nhở", "Nộp thuế thay cho mọi người trong gia đình"], x: "Hiến pháp quy định mọi người phải nộp thuế theo luật. Người nộp thuế phải đăng kí thuế, dùng mã số thuế, kê khai trung thực, đầy đủ và nộp thuế đúng thời hạn; khai sai thì phải chịu trách nhiệm trước pháp luật.", lv: 1 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "tf4", q: "Chị Mai mở một quán bán đồ ăn sáng gần trường học. Mỗi ý sau đúng hay sai?", o: ["Quán nhỏ thì chị Mai không cần quan tâm đến vệ sinh an toàn thực phẩm.", "Chị Mai được tự quyết định bán món gì, quán lớn hay nhỏ, miễn là đúng pháp luật.", "Chị Mai có thể đổ nước thải, rác của quán xuống cống chung cho tiện.", "Khi đông khách, chị Mai có thể mở thêm dịch vụ giao đồ ăn tận nhà."], a: [false, true, false, true], x: "a) Sai: kinh doanh ăn uống phải bảo đảm an toàn thực phẩm cho khách. b) Đúng: chị được tự chọn mặt hàng, quy mô trong khuôn khổ pháp luật. c) Sai: người kinh doanh phải giữ vệ sinh, bảo vệ môi trường. d) Đúng: chị được chủ động mở rộng dịch vụ hợp pháp.", lv: 2 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Một số người bán hàng cố tình khai doanh thu thấp hơn thực tế để nộp ít thuế. Vì sao việc làm này gây hại cho xã hội?", o: ["Ngân sách bị thất thu, kinh doanh không công bằng với người nộp thuế đầy đủ", "Không gây hại gì cho ai vì số tiền thuế khai thiếu thường là rất nhỏ", "Chỉ gây hại cho chính người khai sai, hoàn toàn không ảnh hưởng đến ai khác", "Giúp hàng hoá bán rẻ hơn nên có lợi cho tất cả người tiêu dùng"], x: "Ngân sách nhà nước chủ yếu được hình thành từ thuế, dùng để xây trường học, bệnh viện, đường sá, bảo đảm quốc phòng, an ninh. Khai thấp doanh thu để trốn thuế làm ngân sách thất thu, tạo cạnh tranh không lành mạnh với người kinh doanh trung thực; người vi phạm có thể bị xử lí theo pháp luật.", lv: 2 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Anh Khôi mở xưởng sản xuất đồ gỗ nhưng không đăng kí kinh doanh, thuê công nhân mà không kí hợp đồng lao động. Nhận xét nào dưới đây đúng?", o: ["Anh có quyền làm đồ gỗ nhưng chưa thực hiện đúng nghĩa vụ khi kinh doanh", "Anh Khôi làm đúng vì xưởng là của riêng anh nên anh muốn làm gì cũng được", "Anh Khôi sai vì sản xuất đồ gỗ là ngành nghề bị cấm đầu tư kinh doanh", "Anh Khôi chỉ làm sai khi xưởng của anh có trên một trăm công nhân"], x: "Sản xuất đồ gỗ là ngành nghề pháp luật không cấm nên anh Khôi được kinh doanh. Nhưng khi kinh doanh, anh phải làm thủ tục đăng kí theo quy định, kí hợp đồng và bảo đảm quyền lợi của người lao động.", lv: 2 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "num", q: "Một cửa hàng bán chiếc quạt điện có giá chưa tính thuế giá trị gia tăng là 850 000 đồng. Giả sử thuế suất thuế giá trị gia tăng của mặt hàng này là 10%. Người mua phải trả tất cả bao nhiêu đồng cho chiếc quạt?", ans: 935000, unit: "đồng", x: "Tiền thuế giá trị gia tăng: 850 000 × 10 : 100 = 85 000 (đồng). Người mua phải trả: 850 000 + 85 000 = 935 000 (đồng).", lv: 3 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Bác Sơn định làm nước mắm tại nhà để bán ra thị trường. Lời khuyên nào dưới đây giúp bác kinh doanh đúng pháp luật?", o: ["Đăng kí kinh doanh, giữ vệ sinh an toàn thực phẩm, xử lí nước thải, nộp thuế", "Chỉ bán cho người quen nên không cần đăng kí kinh doanh hay kê khai, nộp thuế gì", "Pha thêm hoá chất tạo màu, tạo mùi để nước mắm trông đẹp và thơm hơn hẳn", "Dán nhãn của một hãng nước mắm nổi tiếng lên chai để bán được giá cao hơn"], x: "Làm nước mắm để bán là ngành nghề pháp luật không cấm; bác Sơn cần đăng kí kinh doanh, bảo đảm an toàn thực phẩm cho người dùng, không gây ô nhiễm môi trường và thực hiện nghĩa vụ thuế. Dùng hoá chất không được phép hay giả nhãn hiệu của hãng khác là vi phạm pháp luật.", lv: 3 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Bố của Nhung bán hàng tạp hoá. Một người quen gợi ý bố nhập hàng không có hoá đơn, giá rẻ, “bán lời nhiều mà khỏi khai thuế”. Nhung nên nói gì với bố?", o: ["Hàng không hoá đơn dễ là hàng lậu, kém chất lượng; bán để trốn thuế là trái luật", "Bố nên nhập thật nhiều hàng đó vì giá nhập càng rẻ thì bán ra càng có lãi nhiều", "Bố chỉ cần bán hết số hàng đó trong một tháng thì sẽ không ai biết được", "Bố nên nhập hàng đó rồi bán thấp hơn giá thị trường để nhanh hết hàng"], x: "Hàng không có hoá đơn, chứng từ thường không rõ nguồn gốc, có thể là hàng nhập lậu, hàng giả. Kinh doanh hàng đó và cố tình không khai để trốn thuế là vi phạm pháp luật, có thể bị xử phạt nặng. Nhung nên khuyên bố chỉ nhập hàng có nguồn gốc, hoá đơn rõ ràng.", lv: 3 }
    ]
  },
  "gdcd9-ck2-de2": {
    note: "Giáo dục công dân 9, sách Kết nối tri thức, cuối năm học: Bài 7 Thích ứng với thay đổi; Bài 8 Tiêu dùng thông minh; trọng tâm Bài 9 Vi phạm pháp luật và trách nhiệm pháp lí, Bài 10 Quyền tự do kinh doanh và nghĩa vụ nộp thuế. Câu về pháp luật theo sách in năm 2026 (Hiến pháp năm 2013 sửa đổi, bổ sung năm 2025; Bộ luật Hình sự năm 2015 sửa đổi, bổ sung năm 2017, 2025; Luật Đầu tư năm 2025). Câu tình huống là chính. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Phạm vi của trường có thể khác, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 9; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Ví dụ nào dưới đây là một thay đổi về môi trường sống?", o: ["Cả nhà chuyển từ nông thôn lên thành phố sinh sống", "Em bị gãy tay, phải bó bột hơn một tháng", "Mẹ được cử đi công tác xa nhà ba tháng", "Người ông thân thiết của em qua đời sau một trận ốm"], x: "Chuyển đến nơi ở mới là thay đổi về môi trường sống: hàng xóm, trường lớp, nếp sinh hoạt đều khác. Bị thương là thay đổi về sức khoẻ; mẹ đi công tác xa là thay đổi trong hoàn cảnh gia đình; người thân qua đời là mất mát lớn của gia đình.", lv: 1 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Chú chó Hoa nuôi từ nhỏ bị lạc mất, Hoa buồn bã nhiều tuần, không muốn làm gì. Mẹ khuyên Hoa ghi lại những kỉ niệm về chú chó, rồi rủ Hoa cùng làm tình nguyện ở một trạm cứu hộ chó mèo. Lời khuyên của mẹ giúp Hoa điều gì?", o: ["Chấp nhận mất mát, vơi nỗi buồn và tìm được niềm vui mới", "Quên ngay chú chó của mình để không còn buồn nữa", "Tránh gặp gỡ mọi người cho đến khi hết buồn hẳn", "Hiểu rằng buồn bã là cảm xúc xấu, không bao giờ nên để mình có"], x: "Mất đi vật nuôi gắn bó là một thay đổi làm ta buồn. Mẹ giúp Hoa chấp nhận sự việc, bày tỏ cảm xúc qua việc ghi lại kỉ niệm và tìm một việc ý nghĩa mới để vượt qua nỗi buồn. Buồn là cảm xúc bình thường; điều quan trọng là không chìm đắm mãi trong đó.", lv: 2 },
      { topic: "Thích ứng với thay đổi", type: "mc", q: "Gia đình Thành chuyển đến một khu chung cư mới. Thành rất ngại làm quen, chiều nào cũng chỉ ở trong nhà xem điện thoại. Theo em, Thành nên làm gì?", o: ["Chủ động chào hỏi hàng xóm, ra sân chơi chung của khu để làm quen bạn mới", "Cứ đóng cửa ở trong nhà cho đến khi tự thấy quen dần với nơi ở mới", "Xin bố mẹ cho chuyển về nhà cũ vì ở đó có nhiều bạn bè thân thiết hơn ở đây", "Chỉ chơi trò chơi trực tuyến với bạn cũ, không cần làm quen bạn mới"], x: "Thay vì thu mình, Thành nên chấp nhận nơi ở mới và chủ động làm quen: chào hỏi hàng xóm, tham gia hoạt động chung của khu, rủ bạn cùng chơi thể thao. Giữ liên lạc với bạn cũ vẫn tốt, nhưng cần mở lòng với bạn mới.", lv: 3 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Khi tìm hiểu một sản phẩm định mua, người tiêu dùng thông minh cần quan tâm những thông tin nào?", o: ["Công dụng, chất lượng, giá cả, mẫu mã của sản phẩm", "Chỉ cần biết sản phẩm có đang được giảm giá hay không", "Chỉ cần biết sản phẩm do người nổi tiếng nào quảng cáo", "Chỉ cần xem sản phẩm có bao bì đẹp, bắt mắt hay không"], x: "Muốn mua đúng sản phẩm, cần tìm hiểu công dụng, chất lượng, giá cả, mẫu mã qua bao bì, trang thông tin của nhà sản xuất, ý kiến người đã dùng… Giảm giá, người nổi tiếng quảng cáo hay bao bì đẹp chưa nói lên chất lượng thật của sản phẩm.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Mẹ của Lan hay mua đồ theo quảng cáo trên mạng, nhiều món mua về để đó không dùng. Lan có thể làm gì để giúp mẹ tiêu dùng thông minh hơn?", o: ["Cùng mẹ lập kế hoạch chi tiêu, xem kĩ thông tin trước khi mua", "Tự ý huỷ mọi đơn hàng của mẹ mà không cần hỏi ý kiến của mẹ", "Khuyên mẹ mỗi lần đi chợ hãy mua thật nhiều để tích trữ cho cả tháng", "Chê bai mọi món đồ mà mẹ đã chọn mua để mẹ không dám mua gì nữa"], x: "Lan có thể cùng mẹ ghi ra những thứ thật sự cần, đặt mức chi tiêu cho mỗi tháng, xem kĩ thông tin sản phẩm và nhận xét của người đã mua trước khi đặt hàng, cảnh giác với lời quảng cáo quá mức. Tự ý huỷ đơn hay chê bai không giúp mẹ thay đổi thói quen.", lv: 1 },
      { topic: "Tiêu dùng thông minh", type: "mc", q: "Khánh muốn mua một đôi giày thể thao. Đôi giày cùng mẫu ở cửa hàng chính hãng giá 900 000 đồng, còn một trang mạng lạ bán 250 000 đồng và cam kết “hàng chính hãng”. Vì sao Khánh nên cân nhắc kĩ lời mời của trang mạng lạ?", o: ["Giá rẻ bất thường, có thể là hàng giả, kém chất lượng hoặc bị lừa mất tiền", "Hàng bán trên mạng lúc nào cũng đắt hơn hàng cùng loại ở các cửa hàng gần nhà", "Giày thể thao theo quy định chỉ được bán ở các cửa hàng chính hãng", "Mọi trang bán hàng trên mạng đều không được phép bán giày dép"], x: "Cùng một mẫu mà giá chưa bằng một phần ba hàng chính hãng là dấu hiệu đáng ngờ. Khánh nên kiểm tra người bán, đọc nhận xét của khách đã mua, so sánh giá ở nhiều nơi, ưu tiên nơi bán uy tín và không chuyển tiền trước cho người bán lạ.", lv: 2 },
      { topic: "Tiêu dùng thông minh", type: "num", q: "Mẹ của Minh cần mua 2 kg bột giặt. Cửa hàng bán cùng một loại bột giặt, cùng hạn sử dụng, gói 500 g giá 32 000 đồng và gói 2 kg giá 112 000 đồng. Nếu mua một gói 2 kg thay vì bốn gói 500 g thì mẹ tiết kiệm được bao nhiêu đồng?", ans: 16000, unit: "đồng", x: "Bốn gói 500 g (đủ 2 kg) có giá 4 × 32 000 = 128 000 (đồng). Mua một gói 2 kg tiết kiệm được 128 000 − 112 000 = 16 000 (đồng). Trước khi mua, so sánh giá theo cùng một khối lượng giúp chọn được cách mua có lợi; nhưng chỉ nên mua gói lớn khi dùng hết trước hạn sử dụng.", lv: 3 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Hành vi trái pháp luật có thể biểu hiện dưới những dạng nào?", o: ["Làm việc pháp luật cấm, không làm việc phải làm, làm sai quy định", "Chỉ là những việc làm gây chết người hoặc gây thiệt hại tới hàng tỉ đồng", "Mọi việc làm khiến người khác không vui, không hài lòng", "Chỉ là những việc làm bị nhiều người chứng kiến, phản đối"], x: "Trái pháp luật là làm việc bị cấm (như trộm cắp), không làm việc mình có nghĩa vụ phải làm (như trốn tránh nghĩa vụ quân sự khi có lệnh gọi), hoặc làm nhưng sai quy định (như xây nhà cao hơn số tầng được cấp phép).", lv: 1 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Trường hợp nào dưới đây KHÔNG phải là áp dụng trách nhiệm pháp lí?", o: ["Một bạn bị cả nhóm phê bình vì hay đến muộn buổi họp nhóm", "Một người bị cảnh sát giao thông phạt tiền vì vượt đèn đỏ", "Một công ti bị Toà án buộc bồi thường cho khách hàng", "Một nhân viên bị giám đốc khiển trách vì vi phạm nội quy"], x: "Trách nhiệm pháp lí do pháp luật quy định và do cơ quan, người có thẩm quyền áp dụng với người vi phạm pháp luật. Bị bạn bè phê bình là nhắc nhở về cách ứng xử, không phải trách nhiệm pháp lí.", lv: 1 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Biện pháp nào dưới đây thuộc trách nhiệm dân sự?", o: ["Buộc xin lỗi, cải chính công khai", "Phạt tù có thời hạn", "Buộc thôi việc", "Tước giấy phép lái xe trong một thời gian"], x: "Trách nhiệm dân sự buộc người vi phạm khôi phục quyền lợi đã bị xâm phạm của người khác, bằng các biện pháp: bồi thường thiệt hại, buộc xin lỗi, cải chính công khai, thực hiện nghĩa vụ dân sự.", lv: 1 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Những văn bản pháp luật nào dưới đây có quy định về trách nhiệm kỉ luật?", o: ["Bộ luật Lao động và Luật Viên chức", "Bộ luật Hình sự và Luật Đầu tư năm 2025", "Luật Biển Việt Nam và Luật Đất đai năm 2024", "Hiến pháp năm 2013 và Luật Bảo vệ môi trường"], x: "Bộ luật Lao động, Luật Cán bộ, công chức, Luật Viên chức… có quy định về trách nhiệm kỉ luật đối với người lao động, cán bộ, công chức, viên chức vi phạm kỉ luật.", lv: 1 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Đêm khuya, anh Vĩnh (25 tuổi) đập phá trạm quan trắc nước đặt ở bờ sông của xã để lấy dây đồng đem bán. Không ai bị thương, nhưng vì sao đây vẫn là hành vi vi phạm pháp luật?", o: ["Vì anh có lỗi khi làm trái pháp luật, xâm hại tài sản chung", "Vì chỉ những việc làm vào ban đêm mới bị coi là vi phạm pháp luật", "Vì anh Vĩnh chưa xin phép chủ tịch xã trước khi lấy dây đồng", "Vì dây đồng là tài sản có giá trị lớn nhất của cả xã"], x: "Anh Vĩnh biết việc làm của mình là sai mà vẫn làm (có lỗi); phá trạm quan trắc (tài sản chung) để lấy đồ bán là làm trái pháp luật, gây thiệt hại cho tài sản của Nhà nước, làm gián đoạn việc theo dõi chất lượng nước. Hành vi đó xâm phạm những quan hệ mà pháp luật bảo vệ, nên dù không ai bị thương vẫn là vi phạm pháp luật.", lv: 2 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Vì sao cùng là làm hư hỏng tài sản của người khác, có trường hợp chỉ phải bồi thường, có trường hợp lại bị truy cứu trách nhiệm hình sự?", o: ["Do mức độ nguy hiểm, lỗi và hậu quả của từng hành vi khác nhau", "Do người có tiền chỉ phải bồi thường, người nghèo thì phải đi tù", "Do việc xử lí hoàn toàn tuỳ theo ý muốn của người bị thiệt hại", "Do hành vi ở thành phố bị xử nặng hơn hành vi ở nông thôn"], x: "Làm hư hỏng tài sản có thể chỉ là vi phạm dân sự (phải bồi thường) khi thiệt hại nhỏ, mức độ nguy hiểm thấp; nhưng nếu hành vi nguy hiểm cho xã hội đến mức Bộ luật Hình sự quy định là tội phạm thì người đó phải chịu trách nhiệm hình sự. Ai vi phạm cũng bị xử lí theo đúng tính chất, mức độ vi phạm.", lv: 2 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Sau khi một cơ sở sản xuất bị xử phạt nặng vì xả nước thải chưa xử lí ra sông và bị buộc khắc phục hậu quả, nhiều cơ sở khác trong vùng đã tự lắp hệ thống xử lí nước thải. Điều đó thể hiện ý nghĩa nào của trách nhiệm pháp lí?", o: ["Răn đe, giáo dục các cơ sở khác tự giác làm theo pháp luật", "Giúp cơ sở bị phạt có thêm tiền để mở rộng quy mô sản xuất", "Làm cho các cơ sở sản xuất phải đóng cửa hết", "Cho phép các cơ sở được xả thải nếu đã nộp phạt"], x: "Trách nhiệm pháp lí không chỉ trừng phạt người vi phạm mà còn giáo dục, răn đe người khác, giúp mọi người tự giác sống, làm việc theo pháp luật, góp phần giữ trật tự chung và giữ gìn môi trường.", lv: 2 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "mc", q: "Chị gái của Thư nhận viết bài quảng cáo bán hàng trên mạng cho một cửa hàng, rồi được nhờ đăng bài bịa chuyện, chê bai một cửa hàng đối thủ để hút khách. Thư nên khuyên chị thế nào?", o: ["Từ chối, vì bịa đặt, bôi nhọ uy tín người khác là trái pháp luật", "Nhận lời, vì ai cũng có quyền nói xấu đối thủ cạnh tranh", "Nhận lời nhưng dùng tài khoản giả để không ai biết mình", "Chỉ nhận lời nếu cửa hàng trả tiền công cao gấp đôi bình thường"], x: "Đăng tin bịa đặt, bôi nhọ uy tín của người khác là trái pháp luật, người vi phạm có thể bị xử lí theo pháp luật; dùng tài khoản giả không làm hành vi bớt sai. Thư nên khuyên chị từ chối, chỉ quảng cáo trung thực về sản phẩm của cửa hàng mình làm.", lv: 3 },
      { topic: "Vi phạm pháp luật và trách nhiệm pháp lí", type: "tf4", q: "Ông Bảy (55 tuổi) xây nhà, để cát, đá tràn ra nửa lòng đường suốt hai tuần, ban đêm không có đèn báo. Mỗi nhận định sau đúng hay sai?", o: ["Ông Bảy chỉ thiếu ý thức, pháp luật không có quy định về việc này.", "Nếu có người đi xe đâm vào đống vật liệu bị thương, ông Bảy có thể phải bồi thường thiệt hại.", "Hàng xóm nên nhắc ông Bảy; nếu ông vẫn không thu dọn thì báo chính quyền địa phương.", "Vì là nhà của mình nên ông Bảy được để vật liệu ở đâu cũng được."], a: [false, true, true, false], x: "a) Sai: để vật liệu chiếm lòng đường, không có đèn báo là trái quy định về trật tự, an toàn giao thông, có thể bị xử phạt. b) Đúng: gây thiệt hại cho người khác thì phải bồi thường. c) Đúng: góp ý trước, rồi báo cơ quan có thẩm quyền là cách ngăn chặn hợp lí. d) Sai: lòng đường là nơi công cộng, không phải của riêng ai.", lv: 3 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Cô Hạnh mới mở cửa hàng bán hoa, lần đầu kê khai thuế nên chưa biết làm thế nào. Khi thực hiện nghĩa vụ nộp thuế, cô Hạnh có quyền nào dưới đây?", o: ["Được hướng dẫn, hỗ trợ và được giữ bí mật thông tin theo luật", "Được tự quyết định có nộp thuế hay không tuỳ tình hình kinh doanh", "Được tự ý giữ lại tiền thuế để làm từ thiện", "Được tự sửa số thuế phải nộp nếu thấy quá cao"], x: "Người nộp thuế được hướng dẫn, hỗ trợ, được cung cấp những thông tin, tài liệu cần thiết, được giữ kín thông tin (trừ các thông tin theo luật phải cung cấp), được hưởng ưu đãi, hoàn thuế theo quy định. Cô Hạnh có thể hỏi cơ quan thuế để được hướng dẫn kê khai.", lv: 1 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Thuế giá trị gia tăng là loại thuế tính trên phần nào?", o: ["Phần giá trị tăng thêm của sản phẩm qua mỗi khâu", "Toàn bộ thu nhập của mỗi người dân trong một năm", "Diện tích đất nông nghiệp mà gia đình đang sử dụng", "Số tiền mỗi người dân gửi tiết kiệm ở ngân hàng"], x: "Thuế giá trị gia tăng là thuế gián thu, tính trên phần giá trị tăng thêm của sản phẩm qua từng khâu đến khi tới tay người tiêu dùng. Thu nhập tính thuế của cá nhân chịu thuế thu nhập cá nhân; đất nông nghiệp chịu thuế sử dụng đất nông nghiệp.", lv: 1 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Theo Bộ luật Hình sự năm 2015 (sửa đổi, bổ sung năm 2017, 2025), người có hành vi trốn thuế có thể bị xử lí như thế nào?", o: ["Bị phạt tiền hoặc phạt tù, có thể bị cấm hành nghề, tịch thu tài sản", "Chỉ bị nhắc nhở, không phải chịu bất kì hình phạt nào", "Chỉ phải nộp lại đúng số tiền thuế đã trốn, không bị phạt", "Bị cấm kinh doanh suốt đời ở mọi ngành nghề"], x: "Theo sách (Điều 200 Bộ luật Hình sự), người trốn thuế có thể bị phạt từ 100 triệu đến 500 triệu đồng hoặc bị phạt tù từ 3 tháng đến 7 năm; ngoài ra có thể bị cấm giữ chức vụ, cấm hành nghề từ 1 đến 5 năm hoặc bị tịch thu tài sản.", lv: 1 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "tf4", q: "Mỗi ý sau về nghĩa vụ nộp thuế đúng hay sai?", o: ["Hộ kinh doanh nhỏ ở chợ cũng phải thực hiện nghĩa vụ thuế theo quy định.", "Thuế là khoản tiền người dân tự nguyện ủng hộ Nhà nước, nộp hay không tuỳ ý.", "Thuế giá trị gia tăng thường đã được tính vào giá hàng hoá, dịch vụ mà người mua trả.", "Cá nhân có thu nhập chịu thuế theo luật phải nộp thuế thu nhập cá nhân."], a: [true, false, true, true], x: "a) Đúng: cá nhân, hộ kinh doanh, hộ gia đình, tổ chức thuộc diện chịu thuế đều phải nộp thuế theo luật. b) Sai: thuế là khoản nộp bắt buộc vào ngân sách nhà nước. c) Đúng: người bán thu thuế giá trị gia tăng qua giá bán rồi nộp vào ngân sách. d) Đúng: thuế thu nhập cá nhân đánh vào thu nhập tính thuế của cá nhân.", lv: 2 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Một cửa hàng bán điện thoại “xách tay” không có hoá đơn, không bảo hành nhưng quảng cáo là “hàng chính hãng, bảo hành 12 tháng”. Nhận xét nào dưới đây đúng?", o: ["Cửa hàng sai vì quảng cáo gian dối, lừa người tiêu dùng", "Cửa hàng làm đúng vì được tự do kinh doanh mọi mặt hàng", "Cửa hàng không sai vì người mua đã đồng ý trả tiền", "Cửa hàng chỉ sai khi có người mua đến tận nơi khiếu nại"], x: "Người kinh doanh được tự chọn mặt hàng nhưng phải tôn trọng, bảo đảm quyền lợi của người tiêu dùng: thông tin trung thực về nguồn gốc, chất lượng, bảo hành. Quảng cáo sai sự thật là hành vi gian dối, trái pháp luật.", lv: 2 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Vì sao những ngành nghề như kinh doanh xăng dầu, dịch vụ cầm đồ phải có đủ điều kiện mới được kinh doanh?", o: ["Vì ảnh hưởng nhiều đến an toàn, trật tự xã hội nên cần được kiểm soát", "Vì Nhà nước muốn hạn chế số người được kinh doanh, làm giàu từ các ngành này", "Vì đây đều là những ngành nghề bị cấm kinh doanh hoàn toàn", "Vì người kinh doanh những ngành này không phải nộp thuế"], x: "Xăng dầu dễ cháy nổ, dịch vụ cầm đồ liên quan đến tài sản, tiền bạc của nhiều người, nên pháp luật đặt ra điều kiện (cơ sở vật chất, phòng cháy, an ninh trật tự…) để kiểm soát. Đủ điều kiện thì vẫn được kinh doanh và phải nộp thuế như các ngành khác.", lv: 2 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Gần nhà Phong có một cơ sở sang chiết khí ga từ bình lớn sang bình nhỏ không tem, nhãn để bán giá rẻ; cơ sở không có giấy phép, không có thiết bị phòng cháy. Phong nên làm gì?", o: ["Kể với bố mẹ để báo chính quyền; khuyên người thân không mua ga ở đó", "Rủ bạn bè, người quen đến mua vì giá rẻ hơn nhiều nơi khác", "Một mình vào cơ sở đó yêu cầu chủ cơ sở đóng cửa ngay", "Không quan tâm vì đó không phải chuyện của gia đình mình"], x: "Sang chiết ga trái phép, không có thiết bị phòng cháy rất dễ gây cháy nổ, nguy hiểm cho cả khu dân cư; đây là kinh doanh trái pháp luật. Phong nên báo người lớn để phản ánh với chính quyền, cơ quan chức năng và không mua sản phẩm không rõ nguồn gốc.", lv: 3 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "tf4", q: "Anh Thắng mở lớp dạy bơi trong hè cho trẻ em. Mỗi việc làm sau của anh Thắng đúng hay sai?", o: ["Anh Thắng niêm yết rõ học phí, thời gian học trước khi nhận học viên.", "Anh bố trí người cứu hộ, phao cứu sinh, thường xuyên kiểm tra chất lượng nước bể bơi.", "Anh nhận số học viên gấp đôi khả năng trông coi để tăng thu nhập.", "Anh cho trẻ chưa biết bơi xuống khu nước sâu khi chưa có người kèm."], a: [true, true, false, false], x: "a) Đúng: công khai giá dịch vụ là tôn trọng quyền lợi của khách hàng. b) Đúng: người kinh doanh phải bảo đảm an toàn cho người học. c), d) Sai: nhận quá khả năng trông coi hay để trẻ xuống nước sâu khi chưa có người kèm đe doạ tính mạng của trẻ.", lv: 3 },
      { topic: "Quyền tự do kinh doanh và nghĩa vụ nộp thuế", type: "mc", q: "Dì Liên mở cửa hàng tạp hoá có bán rượu, thuốc lá. Thấy học sinh lớp 8 đến mua thuốc lá “cho anh trai”, dì vẫn bán vì “khách nào cũng là khách”. Lan nên góp ý với dì thế nào?", o: ["Không bán rượu, thuốc lá cho người dưới 18 tuổi vì trái luật", "Dì làm đúng vì người bán được tự do bán hàng cho bất kì ai mua", "Dì chỉ cần dặn các bạn đừng hút thuốc ở gần cửa hàng", "Dì nên bán với giá cao hơn cho học sinh để các bạn ít mua"], x: "Kinh doanh rượu, thuốc lá phải tuân theo các quy định riêng của pháp luật, trong đó có việc không bán cho người chưa đủ 18 tuổi. Bán cho học sinh vừa trái pháp luật vừa hại sức khoẻ các em. Quyền tự do kinh doanh luôn đi cùng nghĩa vụ tuân thủ pháp luật, bảo vệ người tiêu dùng.", lv: 3 }
    ]
  }
});
